def browser_close(**_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    import time, uuid

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _day_bounds_local():
        ln = datetime.datetime.now()
        start = ln.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _to_local_naive(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            dt = _parse_dt(dt)
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            return dt
        return dt.astimezone().replace(tzinfo=None)

    def _append_invocation(invocations, session_id, tab_id, tool_name, input_payload, status, result=None, error_message=None):
        started = now
        ended = now
        inv = {
            "id": _new_id("pws_call"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": tool_name,
            "input": input_payload,
            "status": status,
            "started_at": _iso(started),
            "ended_at": _iso(ended),
            "duration_ms": int(max(0, (ended - started).total_seconds() * 1000)),
            "error_message": error_message,
            "result": result,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        invocations.append(inv)
        return inv

    def _record_and_return(inv_status, session_id, tab_id, result=None, error_message=None, http_error=None):
        invocations = _load("tool_invocations.json")
        _append_invocation(
            invocations,
            session_id=session_id,
            tab_id=tab_id,
            tool_name="browser_close",
            input_payload={},
            status=inv_status,
            result=result,
            error_message=error_message,
        )
        _save("tool_invocations.json", invocations)

        # bump session last_activity_at/updated_at if session exists
        sessions2 = _load("automation_sessions.json")
        changed = False
        for s2 in sessions2:
            if isinstance(s2, dict) and s2.get("id") == session_id:
                s2["last_activity_at"] = _iso(now)
                s2["updated_at"] = _iso(now)
                changed = True
                break
        if changed:
            _save("automation_sessions.json", sessions2)

        if http_error is not None:
            return http_error
        return {
            "session_id": session_id,
            "tab_id": tab_id,
            "closed": True,
            "invocation": {
                "status": inv_status,
                "error_message": error_message,
            },
        }

    def _enforce_key_and_quota_for_session(session_row, keys_rows, sessions_rows, invocations_rows, artifacts_rows):
        # If session has client_key_id, enforce key is active and daily quotas
        kid = session_row.get("client_key_id")
        if not kid:
            return None, None  # no key context
        krow = next((k for k in keys_rows if isinstance(k, dict) and k.get("id") == kid), None)
        if not krow:
            return _err("UNAUTHORIZED", "client key for session not found"), None
        if krow.get("status") != "active":
            return _err("UNAUTHORIZED", "client key is disabled or revoked"), None

        start, end = _day_bounds_local()

        def _in_today(iso_ts):
            dt = _to_local_naive(iso_ts)
            if dt is None:
                return False
            return start <= dt < end

        # invocations/day
        lim = krow.get("daily_invocation_limit")
        if isinstance(lim, int):
            used = 0
            for inv in invocations_rows:
                if not isinstance(inv, dict):
                    continue
                sid = inv.get("session_id")
                if not sid:
                    continue
                sess = next((s for s in sessions_rows if isinstance(s, dict) and s.get("id") == sid), None)
                if not sess or sess.get("client_key_id") != kid:
                    continue
                if _in_today(inv.get("created_at")):
                    used += 1
            if used >= lim:
                return _err("QUOTA_EXCEEDED", "daily invocation limit exceeded", limit=lim, used=used), krow

        # artifacts bytes/day (not relevant here)
        # sessions/day (not relevant here)
        return None, krow

    # Context resolution: pick a session that can serve a "current page" operation.
    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    keys = _load("client_keys.json")
    invocations_for_quota = _load("tool_invocations.json")
    artifacts_for_quota = _load("artifacts.json")

    # choose a session with an open current_tab_id; if none, choose a session with any open tab and attach it
    chosen_session = None
    chosen_tab = None

    def _tab_by_id(tid):
        return next((t for t in tabs if isinstance(t, dict) and t.get("id") == tid), None)

    # Prefer sessions with explicit current_tab_id pointing to open tab
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") not in ("active", "closing", "errored"):
            continue
        tid = s.get("current_tab_id")
        if not tid:
            continue
        t = _tab_by_id(tid)
        if not t or t.get("session_id") != s.get("id"):
            continue
        if t.get("status") != "open":
            continue
        chosen_session = s
        chosen_tab = t
        break

    # Otherwise pick any session with at least one open tab; auto-attach lowest tab_index
    if chosen_session is None:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") not in ("active", "closing", "errored"):
                continue
            open_tabs = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == s.get("id") and t.get("status") == "open"]
            if not open_tabs:
                continue
            open_tabs.sort(key=lambda r: (r.get("tab_index") if isinstance(r.get("tab_index"), int) else 10**9, r.get("id") or ""))
            chosen_session = s
            chosen_tab = open_tabs[0]
            break

    if chosen_session is None or chosen_tab is None:
        # No session with an open page exists. Must still record an invocation if we can resolve any session;
        # but without a session_id we cannot create a valid tool_invocations row (session_id is required).
        return _err("NOT_FOUND", "No active page/tab to close.", reason="no open tab in any active session")

    # Enforce client key status/quotas when applicable
    qerr, krow = _enforce_key_and_quota_for_session(chosen_session, keys, sessions, invocations_for_quota, artifacts_for_quota)
    if qerr:
        # record failed invocation
        return _record_and_return("failed", chosen_session["id"], chosen_tab["id"], error_message=qerr["error"]["message"], http_error=qerr)

    # Rate limit: per-session 10s window max 30 invocations
    window_s = 10
    max_calls = 30
    cutoff = now - datetime.timedelta(seconds=window_s)

    recent = 0
    for inv in invocations_for_quota:
        if not isinstance(inv, dict):
            continue
        if inv.get("session_id") != chosen_session.get("id"):
            continue
        dt = _parse_dt(inv.get("created_at"))
        if dt and dt >= cutoff:
            recent += 1
    if recent >= max_calls:
        err = _err("RATE_LIMIT", "rate limited: too many requests for session in 10s window", window_seconds=window_s, limit=max_calls)
        return _record_and_return("failed", chosen_session["id"], chosen_tab["id"], error_message=err["error"]["message"], http_error=err)

    # Mutate: close current tab (open->closing->closed)
    if chosen_tab.get("status") != "open":
        err = _err("CONFLICT", "Tab is not open; cannot close.", tab_status=chosen_tab.get("status"))
        return _record_and_return("failed", chosen_session["id"], chosen_tab["id"], error_message=err["error"]["message"], http_error=err)

    # Apply transitions
    chosen_tab["status"] = "closing"
    chosen_tab["updated_at"] = _iso(now)
    chosen_tab["status"] = "closed"
    chosen_tab["closed_at"] = _iso(now)
    chosen_tab["updated_at"] = _iso(now)

    # If closing current tab, re-point session current_tab_id to lowest-index open tab or null
    sid = chosen_session["id"]
    remaining_open = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == sid and t.get("status") == "open" and t.get("id") != chosen_tab.get("id")]
    if remaining_open:
        remaining_open.sort(key=lambda r: (r.get("tab_index") if isinstance(r.get("tab_index"), int) else 10**9, r.get("id") or ""))
        chosen_session["current_tab_id"] = remaining_open[0].get("id")
    else:
        chosen_session["current_tab_id"] = None
    chosen_session["last_activity_at"] = _iso(now)
    chosen_session["updated_at"] = _iso(now)

    # Persist
    _save("browser_tabs.json", tabs)
    _save("automation_sessions.json", sessions)

    # key last_used_at
    if krow is not None:
        for k in keys:
            if isinstance(k, dict) and k.get("id") == krow.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("client_keys.json", keys)

    return _record_and_return(
        "succeeded",
        chosen_session["id"],
        chosen_tab["id"],
        result={"closed_tab_id": chosen_tab["id"], "new_current_tab_id": chosen_session.get("current_tab_id")},
        error_message=None,
        http_error=None,
    )

def browser_resize(width, height, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        try:
            s = v
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _day_bounds_utc(now):
        start = now.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    t0 = time.time()
    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    invocations = _load("tool_invocations.json")
    keys = _load("client_keys.json")

    # Validate inputs first
    if not isinstance(width, (int, float)) or not isinstance(height, (int, float)):
        return _err("VALIDATION_ERROR", "width and height must be numbers.")
    if isinstance(width, bool) or isinstance(height, bool):
        return _err("VALIDATION_ERROR", "width and height must be numbers.")
    w = int(width)
    h = int(height)
    if w != width and isinstance(width, float) and abs(width - int(width)) > 0:
        # accept floats but coerce; still ensure positive and within bounds
        w = int(round(width))
    if h != height and isinstance(height, float) and abs(height - int(height)) > 0:
        h = int(round(height))
    if w < 100 or w > 10000 or h < 100 or h > 10000:
        return _err("VALIDATION_ERROR", "width and height must be between 100 and 10000.", width=w, height=h)

    def _count_invocations_for_key(kid):
        now = _now()
        day_start, day_end = _day_bounds_utc(now)
        c = 0
        for inv in invocations:
            sid = inv.get("session_id")
            if not sid:
                continue
            s = next((x for x in sessions if x.get("id") == sid), None)
            if not s or s.get("client_key_id") != kid:
                continue
            ca = _parse_dt(inv.get("created_at"))
            if ca and day_start <= ca < day_end:
                c += 1
        return c

    def _select_authorized_session():
        active_keys_by_id = {k.get("id"): k for k in keys if k.get("status") == "active"}
        any_key_enabled = len(keys) > 0
        candidates = []
        for s in sessions:
            if s.get("status") not in ("active", "closing", "errored"):
                continue
            kid = s.get("client_key_id")
            if any_key_enabled:
                if not kid:
                    continue
                k = active_keys_by_id.get(kid)
                if not k:
                    continue
                lim = k.get("daily_invocation_limit")
                if isinstance(lim, int) and _count_invocations_for_key(kid) >= lim:
                    continue
            candidates.append(s)
        if not candidates:
            return None, _err("UNAUTHORIZED", "No authorized session available for this request.")
        # Prefer session with a current open/closing tab (since resize requires active page/window)
        def _has_active_tab(s):
            tid = s.get("current_tab_id")
            if not tid:
                return False
            t = next((x for x in tabs if x.get("id") == tid and x.get("session_id") == s.get("id")), None)
            return bool(t and t.get("status") in ("open", "closing"))
        candidates.sort(key=lambda s: (0 if _has_active_tab(s) else 1, s.get("created_at") or ""))
        return candidates[0], None

    def _log_invocation(session, tab_id_for_log, input_payload, final_status, result=None, error_message=None):
        now = _now()
        dur = int(round((time.time() - t0) * 1000))
        inv_id = _new_id("inv")
        invocations.append({
            "id": inv_id,
            "session_id": session["id"],
            "tab_id": tab_id_for_log,
            "tool_name": "browser_resize",
            "input": input_payload,
            "status": final_status,
            "started_at": _iso(now),
            "ended_at": _iso(now),
            "duration_ms": max(0, dur),
            "error_message": error_message,
            "result": result,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("tool_invocations.json", invocations)

    try:
        session, auth_err = _select_authorized_session()
        if auth_err:
            return auth_err

        now = _now()
        session["viewport_width"] = w
        session["viewport_height"] = h
        session["last_activity_at"] = _iso(now)
        session["updated_at"] = _iso(now)

        tab_id = session.get("current_tab_id")
        if not tab_id:
            _log_invocation(session, None, {"width": width, "height": height}, "failed", result=None, error_message="no active tab")
            _save("automation_sessions.json", sessions)
            return _err("NOT_FOUND", "No active page/window to resize.", reason="no active tab")

        tab = next((t for t in tabs if t.get("id") == tab_id and t.get("session_id") == session.get("id")), None)
        if not tab or tab.get("status") not in ("open", "closing"):
            _log_invocation(session, tab_id, {"width": width, "height": height}, "failed", result=None, error_message="tab not open")
            _save("automation_sessions.json", sessions)
            return _err("NOT_FOUND", "No active page/window to resize.", reason="tab not open")

        _save("automation_sessions.json", sessions)

        result = {"viewport_width": w, "viewport_height": h}
        _log_invocation(session, tab_id, {"width": width, "height": height}, "succeeded", result=result, error_message=None)
        return {"session_id": session["id"], "result": result}
    except Exception as e:
        try:
            if "session" in locals() and session:
                _log_invocation(session, session.get("current_tab_id"), {"width": width, "height": height}, "failed", result=None, error_message=str(e))
        except Exception:
            pass
        return _err("CONFLICT", "Internal error while processing request.", detail=str(e))

def browser_console_messages(**_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    import time, uuid

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _day_bounds_local():
        ln = datetime.datetime.now()
        start = ln.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _to_local_naive(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            dt = _parse_dt(dt)
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            return dt
        return dt.astimezone().replace(tzinfo=None)

    def _append_invocation(invocations, session_id, tab_id, tool_name, input_payload, status, result=None, error_message=None):
        started = now
        ended = now
        inv = {
            "id": _new_id("pws_call"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": tool_name,
            "input": input_payload,
            "status": status,
            "started_at": _iso(started),
            "ended_at": _iso(ended),
            "duration_ms": int(max(0, (ended - started).total_seconds() * 1000)),
            "error_message": error_message,
            "result": result,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        invocations.append(inv)
        return inv

    def _enforce_key_and_quota_for_session(session_row, keys_rows, sessions_rows, invocations_rows):
        kid = session_row.get("client_key_id")
        if not kid:
            return None, None
        krow = next((k for k in keys_rows if isinstance(k, dict) and k.get("id") == kid), None)
        if not krow:
            return _err("UNAUTHORIZED", "client key for session not found"), None
        if krow.get("status") != "active":
            return _err("UNAUTHORIZED", "client key is disabled or revoked"), None

        # daily invocation limit
        lim = krow.get("daily_invocation_limit")
        if isinstance(lim, int):
            start, end = _day_bounds_local()

            def _in_today(iso_ts):
                dt = _to_local_naive(iso_ts)
                if dt is None:
                    return False
                return start <= dt < end

            used = 0
            for inv in invocations_rows:
                if not isinstance(inv, dict):
                    continue
                sid = inv.get("session_id")
                if not sid:
                    continue
                sess = next((s for s in sessions_rows if isinstance(s, dict) and s.get("id") == sid), None)
                if not sess or sess.get("client_key_id") != kid:
                    continue
                if _in_today(inv.get("created_at")):
                    used += 1
            if used >= lim:
                return _err("QUOTA_EXCEEDED", "daily invocation limit exceeded", limit=lim, used=used), krow

        return None, krow

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    keys = _load("client_keys.json")
    invocations = _load("tool_invocations.json")
    observations = _load("page_observations.json")

    # Resolve context: prefer session.current_tab_id open, else attach first open tab in an active session.
    chosen_session = None
    chosen_tab = None

    def _tab_by_id(tid):
        return next((t for t in tabs if isinstance(t, dict) and t.get("id") == tid), None)

    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") not in ("active", "closing", "errored"):
            continue
        tid = s.get("current_tab_id")
        if not tid:
            continue
        t = _tab_by_id(tid)
        if not t or t.get("session_id") != s.get("id"):
            continue
        if t.get("status") != "open":
            continue
        chosen_session, chosen_tab = s, t
        break

    if chosen_session is None:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") not in ("active", "closing", "errored"):
                continue
            open_tabs = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == s.get("id") and t.get("status") == "open"]
            if not open_tabs:
                continue
            open_tabs.sort(key=lambda r: (r.get("tab_index") if isinstance(r.get("tab_index"), int) else 10**9, r.get("id") or ""))
            chosen_session, chosen_tab = s, open_tabs[0]
            # auto-attach it (server behavior: tools operate on current_tab_id)
            chosen_session["current_tab_id"] = chosen_tab.get("id")
            chosen_session["updated_at"] = _iso(now)
            chosen_session["last_activity_at"] = _iso(now)
            _save("automation_sessions.json", sessions)
            break

    if chosen_session is None or chosen_tab is None:
        return _err("NOT_FOUND", "No active page to read console messages from.", reason="no open tab in any active session")

    # enforce key/quotas when applicable
    qerr, krow = _enforce_key_and_quota_for_session(chosen_session, keys, sessions, invocations)
    if qerr:
        _append_invocation(invocations, chosen_session["id"], chosen_tab["id"], "browser_console_messages", {}, "failed", result=None, error_message=qerr["error"]["message"])
        _save("tool_invocations.json", invocations)
        return qerr

    # Rate limit: per-session 10s window max 30 invocations
    window_s = 10
    max_calls = 30
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("session_id") != chosen_session.get("id"):
            continue
        dt = _parse_dt(inv.get("created_at"))
        if dt and dt >= cutoff:
            recent += 1
    if recent >= max_calls:
        err = _err("RATE_LIMIT", "rate limited: too many requests for session in 10s window", window_seconds=window_s, limit=max_calls)
        _append_invocation(invocations, chosen_session["id"], chosen_tab["id"], "browser_console_messages", {}, "failed", result=None, error_message=err["error"]["message"])
        _save("tool_invocations.json", invocations)
        return err

    # Collect messages for tab, cap at last 500
    msgs = []
    for ob in observations:
        if not isinstance(ob, dict):
            continue
        if ob.get("session_id") != chosen_session.get("id"):
            continue
        if ob.get("tab_id") != chosen_tab.get("id"):
            continue
        if ob.get("kind") != "console_message":
            continue
        if ob.get("status") == "deleted":
            continue
        payload = ob.get("payload")
        if isinstance(payload, dict):
            msgs.append({"occurred_at": ob.get("occurred_at"), **payload})
        else:
            msgs.append({"occurred_at": ob.get("occurred_at"), "payload": payload})

    msgs.sort(key=lambda m: (_parse_dt(m.get("occurred_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)))
    truncated = False
    if len(msgs) > 500:
        msgs = msgs[-500:]
        truncated = True

    result_meta = {"count": len(msgs), "truncated": truncated, "limit": 500}
    _append_invocation(invocations, chosen_session["id"], chosen_tab["id"], "browser_console_messages", {}, "succeeded", result=result_meta, error_message=None)
    _save("tool_invocations.json", invocations)

    # session activity + key last_used_at
    chosen_session["last_activity_at"] = _iso(now)
    chosen_session["updated_at"] = _iso(now)
    _save("automation_sessions.json", sessions)
    if krow is not None:
        for k in keys:
            if isinstance(k, dict) and k.get("id") == krow.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("client_keys.json", keys)

    return {"session_id": chosen_session["id"], "tab_id": chosen_tab["id"], "messages": msgs, "meta": result_meta}

def browser_file_upload(paths, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    import time, uuid

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _day_bounds_local():
        ln = datetime.datetime.now()
        start = ln.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _to_local_naive(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            dt = _parse_dt(dt)
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            return dt
        return dt.astimezone().replace(tzinfo=None)

    # Validate inputs (allow any non-empty strings as "paths", including s3://...)
    if not isinstance(paths, list) or len(paths) == 0:
        return _err("VALIDATION_ERROR", "paths must be a non-empty array of strings.")
    for p in paths:
        if not isinstance(p, str) or not p.strip():
            return _err("VALIDATION_ERROR", "paths must contain only non-empty strings.")

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    keys = _load("client_keys.json")
    invocations = _load("tool_invocations.json")
    observations = _load("page_observations.json")

    def _append_invocation(session_id, tab_id, status, result=None, error_message=None):
        started = now
        ended = now
        inv = {
            "id": _new_id("pws_call"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_file_upload",
            "input": {"paths": paths},
            "status": status,
            "started_at": _iso(started),
            "ended_at": _iso(ended),
            "duration_ms": int(max(0, (ended - started).total_seconds() * 1000)),
            "error_message": error_message,
            "result": result,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        invocations.append(inv)
        return inv

    def _enforce_key_and_quota(session_row):
        kid = session_row.get("client_key_id")
        if not kid:
            return None, None
        krow = next((k for k in keys if isinstance(k, dict) and k.get("id") == kid), None)
        if not krow:
            return _err("UNAUTHORIZED", "client key for session not found"), None
        if krow.get("status") != "active":
            return _err("UNAUTHORIZED", "client key is disabled or revoked"), None
        lim = krow.get("daily_invocation_limit")
        if isinstance(lim, int):
            start, end = _day_bounds_local()

            def _in_today(iso_ts):
                dt = _to_local_naive(iso_ts)
                if dt is None:
                    return False
                return start <= dt < end

            used = 0
            for inv in invocations:
                if not isinstance(inv, dict):
                    continue
                sid = inv.get("session_id")
                if not sid:
                    continue
                sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sid), None)
                if not sess or sess.get("client_key_id") != kid:
                    continue
                if _in_today(inv.get("created_at")):
                    used += 1
            if used >= lim:
                return _err("QUOTA_EXCEEDED", "daily invocation limit exceeded", limit=lim, used=used), krow
        return None, krow

    # Resolve context: current tab open; else attach first open tab in an active session
    chosen_session = None
    chosen_tab = None

    def _tab_by_id(tid):
        return next((t for t in tabs if isinstance(t, dict) and t.get("id") == tid), None)

    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") not in ("active", "closing", "errored"):
            continue
        tid = s.get("current_tab_id")
        if not tid:
            continue
        t = _tab_by_id(tid)
        if not t or t.get("session_id") != s.get("id"):
            continue
        if t.get("status") != "open":
            continue
        chosen_session, chosen_tab = s, t
        break

    if chosen_session is None:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") not in ("active", "closing", "errored"):
                continue
            open_tabs = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == s.get("id") and t.get("status") == "open"]
            if not open_tabs:
                continue
            open_tabs.sort(key=lambda r: (r.get("tab_index") if isinstance(r.get("tab_index"), int) else 10**9, r.get("id") or ""))
            chosen_session, chosen_tab = s, open_tabs[0]
            chosen_session["current_tab_id"] = chosen_tab.get("id")
            chosen_session["updated_at"] = _iso(now)
            chosen_session["last_activity_at"] = _iso(now)
            _save("automation_sessions.json", sessions)
            break

    if chosen_session is None or chosen_tab is None:
        return _err("NOT_FOUND", "No active page/tab to upload files on.", reason="no open tab in any active session")

    # enforce key/quotas when applicable
    qerr, krow = _enforce_key_and_quota(chosen_session)
    if qerr:
        _append_invocation(chosen_session["id"], chosen_tab["id"], "failed", result=None, error_message=qerr["error"]["message"])
        _save("tool_invocations.json", invocations)
        return qerr

    # Rate limit: per-session 10s window max 30 invocations
    window_s = 10
    max_calls = 30
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("session_id") != chosen_session.get("id"):
            continue
        dt = _parse_dt(inv.get("created_at"))
        if dt and dt >= cutoff:
            recent += 1
    if recent >= max_calls:
        err = _err("RATE_LIMIT", "rate limited: too many requests for session in 10s window", window_seconds=window_s, limit=max_calls)
        _append_invocation(chosen_session["id"], chosen_tab["id"], "failed", result=None, error_message=err["error"]["message"])
        _save("tool_invocations.json", invocations)
        return err

    # Realistic backend behavior in this datastore-only server:
    # There may be no explicit "file chooser waiting" state in the schema. Treat upload as setting the file input
    # in the session log, but require an open tab (already ensured).
    _append_invocation(chosen_session["id"], chosen_tab["id"], "succeeded", result={"uploaded": True, "file_count": len(paths)}, error_message=None)
    _save("tool_invocations.json", invocations)

    chosen_session["last_activity_at"] = _iso(now)
    chosen_session["updated_at"] = _iso(now)
    _save("automation_sessions.json", sessions)
    if krow is not None:
        for k in keys:
            if isinstance(k, dict) and k.get("id") == krow.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("client_keys.json", keys)

    return {"session_id": chosen_session["id"], "tab_id": chosen_tab["id"], "uploaded": True, "paths": paths}

