            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    inv = _load("tool_invocations.json")
    obs = _load("page_observations.json")
    keys = _load("client_keys.json")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    session = None
    key_row = None
    tab = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") not in ("active", "closing", "errored"):
            continue
        ctid = s.get("current_tab_id")
        if not ctid:
            continue
        t = next((x for x in tabs if isinstance(x, dict) and x.get("id") == ctid and x.get("session_id") == s.get("id")), None)
        if not t:
            continue
        if t.get("status") != "open":
            continue
        kid = s.get("client_key_id")
        if kid is not None:
            kr = next((k for k in keys if isinstance(k, dict) and k.get("id") == kid), None)
            if not kr:
                continue
            if kr.get("status") != "active":
                continue
            key_row = kr
        session = s
        tab = t
        break

    if not session or not tab:
        return _err("NOT_FOUND", "no active tab")

    # Quota: daily_invocation_limit (this endpoint logs an invocation too)
    if key_row and key_row.get("daily_invocation_limit") is not None:
        try:
            limit = int(key_row.get("daily_invocation_limit"))
            if limit >= 0:
                start_day = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
                used = 0
                sid = session.get("id")
                for r in inv:
                    if not isinstance(r, dict):
                        continue
                    if r.get("session_id") != sid:
                        continue
                    try:
                        ca = datetime.datetime.fromisoformat(r.get("created_at"))
                    except Exception:
                        continue
                    if ca.tzinfo is None:
                        ca = ca.replace(tzinfo=datetime.timezone.utc)
                    if ca >= start_day and ca <= now:
                        used += 1
                if used >= limit:
                    return _err("QUOTA_EXCEEDED", "daily invocation limit exceeded", limit=limit)
        except Exception:
            return _err("VALIDATION_ERROR", "invalid daily_invocation_limit configuration")

    invocation_id = _gen_id("inv")
    inv_row = {
        "id": invocation_id,
        "session_id": session["id"],
        "tab_id": tab["id"],
        "tool_name": "browser_network_requests",
        "input": {},
        "status": "running",
        "started_at": now_s,
        "ended_at": None,
        "duration_ms": None,
        "error_message": None,
        "result": None,
        "created_at": now_s,
        "updated_at": now_s,
    }
    inv.append(inv_row)

    session["last_activity_at"] = now_s
    session["updated_at"] = now_s

    # Since last navigation OR since opened: implement since last navigate* invocation ended_at, else tab.opened_at
    cutoff = None
    last_nav = None
    for r in inv:
        if not isinstance(r, dict):
            continue
        if r.get("session_id") != session["id"]:
            continue
        if r.get("tab_id") != tab["id"]:
            continue
        if r.get("status") != "succeeded":
            continue
        if r.get("tool_name") not in ("browser_navigate", "browser_navigate_back", "browser_navigate_forward"):
            continue
        ea = r.get("ended_at") or r.get("started_at")
        if not ea:
            continue
        try:
            dt = datetime.datetime.fromisoformat(ea)
        except Exception:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if (last_nav is None) or (dt > last_nav):
            last_nav = dt
    if last_nav is not None:
        cutoff = last_nav
    else:
        try:
            oa = datetime.datetime.fromisoformat(tab.get("opened_at"))
            if oa.tzinfo is None:
                oa = oa.replace(tzinfo=datetime.timezone.utc)
            cutoff = oa
        except Exception:
            cutoff = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    # Filter observations
    items = []
    truncated = False
    for o in obs:
        if not isinstance(o, dict):
            continue
        if o.get("status") != "recorded":
            continue
        if o.get("kind") != "network_request":
            continue
        if o.get("session_id") != session["id"] or o.get("tab_id") != tab["id"]:
            continue
        try:
            occ = datetime.datetime.fromisoformat(o.get("occurred_at"))
        except Exception:
            continue
        if occ.tzinfo is None:
            occ = occ.replace(tzinfo=datetime.timezone.utc)
        if occ >= cutoff:
            items.append(o)

    items.sort(key=lambda x: x.get("occurred_at") or "")
    cap = 500
    if len(items) > cap:
        items = items[-cap:]
        truncated = True

    end_s = datetime.datetime.now(datetime.timezone.utc).isoformat()
    inv_row["status"] = "succeeded"
    inv_row["ended_at"] = end_s
    inv_row["duration_ms"] = int((time.time() - t0) * 1000)
    inv_row["result"] = {
        "since": cutoff.isoformat(),
        "count": len(items),
        "truncated": bool(truncated),
        "cap": cap,
    }
    inv_row["updated_at"] = end_s

    if key_row:
        key_row["last_used_at"] = end_s
        key_row["updated_at"] = end_s
        _save("client_keys.json", keys)

    _save("automation_sessions.json", sessions)
    _save("tool_invocations.json", inv)

    # Return just the network payload list (plus minimal metadata)
    return {
        "session_id": session["id"],
        "tab_id": tab["id"],
        "since": cutoff.isoformat(),
        "requests": [o.get("payload") for o in items],
        "truncated": bool(truncated),
        "cap": cap,
    }

def browser_pdf_save(filename=None, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    # Validate filename
    if filename is not None:
        if not isinstance(filename, str):
            return _err("VALIDATION_ERROR", "filename must be a string")
        fn = filename.strip()
        if fn == "":
            return _err("VALIDATION_ERROR", "filename cannot be empty")
        if len(fn) > 255:
            return _err("VALIDATION_ERROR", "filename too long")
        if "/" in fn or "\\" in fn or "\x00" in fn:
            return _err("VALIDATION_ERROR", "filename must be a base name without path separators")
        filename = fn

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    inv = _load("tool_invocations.json")
    artifacts = _load("artifacts.json")
    keys = _load("client_keys.json")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    session = None
    key_row = None
    tab = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") not in ("active", "closing", "errored"):
            continue
        ctid = s.get("current_tab_id")
        if not ctid:
            continue
        t = next((x for x in tabs if isinstance(x, dict) and x.get("id") == ctid and x.get("session_id") == s.get("id")), None)
        if not t:
            continue
        kid = s.get("client_key_id")
        if kid is not None:
            kr = next((k for k in keys if isinstance(k, dict) and k.get("id") == kid), None)
            if not kr:
                continue
            if kr.get("status") != "active":
                continue
            key_row = kr
        session = s
        tab = t
        break

    if not session or not tab:
        return _err("NOT_FOUND", "no active session/tab to render")

    if tab.get("status") != "open":
        return _err("NOT_FOUND", "target page has been closed")

    # Quotas: daily_invocation_limit and daily_artifact_bytes_limit
    if key_row:
        start_day = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)

        if key_row.get("daily_invocation_limit") is not None:
            try:
                limit = int(key_row.get("daily_invocation_limit"))
                if limit >= 0:
                    used = 0
                    sid = session.get("id")
                    for r in inv:
                        if not isinstance(r, dict):
                            continue
                        if r.get("session_id") != sid:
                            continue
                        try:
                            ca = datetime.datetime.fromisoformat(r.get("created_at"))
                        except Exception:
                            continue
                        if ca.tzinfo is None:
                            ca = ca.replace(tzinfo=datetime.timezone.utc)
                        if ca >= start_day and ca <= now:
                            used += 1
                    if used >= limit:
                        return _err("QUOTA_EXCEEDED", "daily invocation limit exceeded", limit=limit)
            except Exception:
                return _err("VALIDATION_ERROR", "invalid daily_invocation_limit configuration")

        if key_row.get("daily_artifact_bytes_limit") is not None:
            try:
                blimit = int(key_row.get("daily_artifact_bytes_limit"))
                if blimit >= 0:
                    used_bytes = 0
                    sid = session.get("id")
                    for a in artifacts:
                        if not isinstance(a, dict):
                            continue
                        if a.get("session_id") != sid:
                            continue
                        try:
                            ca = datetime.datetime.fromisoformat(a.get("created_at"))
                        except Exception:
                            continue
                        if ca.tzinfo is None:
                            ca = ca.replace(tzinfo=datetime.timezone.utc)
                        if ca >= start_day and ca <= now and a.get("status") in ("writing", "available"):
                            try:
                                used_bytes += int(a.get("byte_size", 0))
                            except Exception:
                                pass
                    # We'll estimate pdf size below; enforce after computed too.
                    if used_bytes >= blimit:
                        return _err("QUOTA_EXCEEDED", "daily artifact bytes limit exceeded", limit=blimit)
            except Exception:
                return _err("VALIDATION_ERROR", "invalid daily_artifact_bytes_limit configuration")

    # Log invocation
    invocation_id = _gen_id("inv")
    inv_row = {
        "id": invocation_id,
        "session_id": session["id"],
        "tab_id": tab["id"],
        "tool_name": "browser_pdf_save",
        "input": {"filename": filename} if filename is not None else {},
        "status": "running",
        "started_at": now_s,
        "ended_at": None,
        "duration_ms": None,
        "error_message": None,
        "result": None,
        "created_at": now_s,
        "updated_at": now_s,
    }
    inv.append(inv_row)

    session["last_activity_at"] = now_s
    session["updated_at"] = now_s

    # Create artifact file (local_fs)
    ts = int(now.timestamp())
    if filename is None:
        filename = f"page-{ts}.pdf"

    os.makedirs(os.path.join(_DB, "artifacts"), exist_ok=True)
    artifact_id = _gen_id("art")
    storage_path = os.path.join(_DB, "artifacts", f"{artifact_id}-{filename}")
    storage_uri = storage_path

    # Create minimal PDF bytes (synthetic, but persisted and consistent)
    pdf_bytes = (b"%PDF-1.4\n% Synthetic PDF generated by offline datastore\n"
                 b"1 0 obj<<>>endobj\ntrailer<<>>\n%%EOF\n")

    try:
        with open(storage_path, "wb") as f:
            f.write(pdf_bytes)
    except Exception:
        end_s = datetime.datetime.now(datetime.timezone.utc).isoformat()
        inv_row["status"] = "failed"
        inv_row["ended_at"] = end_s
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        inv_row["error_message"] = "failed to write pdf to storage backend"
        inv_row["updated_at"] = end_s
        _save("tool_invocations.json", inv)
        _save("automation_sessions.json", sessions)
        return _err("CONFLICT", "failed to write artifact")

    byte_size = len(pdf_bytes)
    sha256 = hashlib.sha256(pdf_bytes).hexdigest()

    # Enforce bytes quota after knowing size
    if key_row and key_row.get("daily_artifact_bytes_limit") is not None:
        try:
            blimit = int(key_row.get("daily_artifact_bytes_limit"))
            if blimit >= 0:
                start_day = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
                used_bytes = 0
                sid = session.get("id")
                for a in artifacts:
                    if not isinstance(a, dict):
                        continue
                    if a.get("session_id") != sid:
                        continue
                    try:
                        ca = datetime.datetime.fromisoformat(a.get("created_at"))
                    except Exception:
                        continue
                    if ca.tzinfo is None:
                        ca = ca.replace(tzinfo=datetime.timezone.utc)
                    if ca >= start_day and ca <= now and a.get("status") in ("writing", "available"):
                        try:
                            used_bytes += int(a.get("byte_size", 0))
                        except Exception:
                            pass
                if used_bytes + byte_size > blimit:
                    # Mark invocation failed and delete file
                    try:
                        os.remove(storage_path)
                    except Exception:
                        pass
                    end_s = datetime.datetime.now(datetime.timezone.utc).isoformat()
                    inv_row["status"] = "failed"
                    inv_row["ended_at"] = end_s
                    inv_row["duration_ms"] = int((time.time() - t0) * 1000)
                    inv_row["error_message"] = "daily artifact bytes limit exceeded"
                    inv_row["updated_at"] = end_s
                    _save("tool_invocations.json", inv)
                    _save("automation_sessions.json", sessions)
                    return _err("QUOTA_EXCEEDED", "daily artifact bytes limit exceeded", limit=blimit)
        except Exception:
            return _err("VALIDATION_ERROR", "invalid daily_artifact_bytes_limit configuration")

    art_row = {
        "id": artifact_id,
        "session_id": session["id"],
        "tab_id": tab["id"],
        "invocation_id": invocation_id,
        "artifact_type": "pdf",
        "filename": filename,
        "content_type": "application/pdf",
        "byte_size": byte_size,
        "storage_backend": "local_fs",
        "storage_uri": storage_uri,
        "sha256": sha256,
        "status": "available",
        "created_at": now_s,
        "updated_at": now_s,
    }
    artifacts.append(art_row)

    end_s = datetime.datetime.now(datetime.timezone.utc).isoformat()
    inv_row["status"] = "succeeded"
    inv_row["ended_at"] = end_s
    inv_row["duration_ms"] = int((time.time() - t0) * 1000)
    inv_row["result"] = {"artifact_id": artifact_id, "filename": filename, "byte_size": byte_size}
    inv_row["updated_at"] = end_s

    if key_row:
        key_row["last_used_at"] = end_s
        key_row["updated_at"] = end_s
        _save("client_keys.json", keys)

    _save("artifacts.json", artifacts)
    _save("tool_invocations.json", inv)
    _save("automation_sessions.json", sessions)

    return {
        "artifact": art_row,
        "pdf_bytes": pdf_bytes,
    }

def browser_take_screenshot(raw=None, filename=None, element=None, ref=None, **_extra):
    import json, os, datetime, time, uuid, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _parse_dt(v):
        if v is None: return None
        if isinstance(v, datetime.datetime): return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            try:
                if s.endswith("Z"): s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _today_local_date_str():
        return datetime.datetime.now().date().isoformat()

    def _to_local_naive(dt):
        if dt is None: return None
        if isinstance(dt, str): dt = _parse_dt(dt)
        if not isinstance(dt, datetime.datetime): return None
        if dt.tzinfo is None: return dt
        return dt.astimezone().replace(tzinfo=None)

    # Validate inputs per schema/tool rules
    if raw is None:
        raw = False
    if not isinstance(raw, bool):
        return _err("VALIDATION_ERROR", "raw must be a boolean.")
    if filename is not None and (not isinstance(filename, str) or not filename.strip()):
        return _err("VALIDATION_ERROR", "filename must be a non-empty string when provided.")
    if (element is None) ^ (ref is None):
        return _err("VALIDATION_ERROR", "element and ref must be provided together (or both omitted).", rule="element_ref_pair")
    if element is not None and (not isinstance(element, str) or not element.strip()):
        return _err("VALIDATION_ERROR", "element must be a non-empty string when provided.")
    if ref is not None and (not isinstance(ref, str) or not ref.strip()):
        return _err("VALIDATION_ERROR", "ref must be a non-empty string when provided.")

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    invocations = _load("tool_invocations.json")
    observations = _load("page_observations.json")
    artifacts = _load("artifacts.json")
    keys = _load("client_keys.json")

    # Choose an accessible active session with an open current tab
    sess = None
    tab = None
    for s in sessions:
        if not isinstance(s, dict): 
            continue
        if s.get("status") != "active":
            continue
        ctid = s.get("current_tab_id")
        if not ctid:
            continue
        t = next((x for x in tabs if isinstance(x, dict) and x.get("id") == ctid and x.get("session_id") == s.get("id")), None)
        if t and t.get("status") == "open":
            sess, tab = s, t
            break
    if not sess:
        # Log failed invocation (no active tab)
        created = _iso(now)
        inv_id = _new_id("pws_call")
        row = {
            "id": inv_id,
            "session_id": (next((s.get("id") for s in sessions if isinstance(s, dict) and s.get("status") == "active"), "") or ""),
            "tab_id": None,
            "tool_name": "browser_take_screenshot",
            "input": {"raw": raw, **({} if filename is None else {"filename": filename}), **({} if element is None else {"element": element, "ref": ref})},
            "status": "failed",
            "started_at": created,
            "ended_at": created,
            "duration_ms": int(max(0, (time.time() - t0) * 1000)),
            "error_message": "no active tab",
            "result": None,
            "created_at": created,
            "updated_at": created,
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No active tab.", reason="no_active_tab")

    session_id = sess.get("id")
    tab_id = tab.get("id")
    created = _iso(now)

    # Enforce key status/quota if key exists for this session
    ckid = sess.get("client_key_id")
    key_row = None
    if ckid:
        key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == ckid), None)
        if not key_row:
            return _err("UNAUTHORIZED", "client key for session not found.")
        if key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "client key is not active.", key_status=key_row.get("status"))
        # daily_artifact_bytes_limit
        lim = key_row.get("daily_artifact_bytes_limit")
        if isinstance(lim, int):
            today = _today_local_date_str()
            used = 0
            for a in artifacts:
                if not isinstance(a, dict): 
                    continue
                if a.get("session_id") and next((s for s in sessions if isinstance(s, dict) and s.get("id") == a.get("session_id")), {}).get("client_key_id") != ckid:
                    continue
                ca = a.get("created_at")
                if (ca or "")[:10] != today:
                    # created_at stored in Z; compare by date prefix as pragmatic local/utc guard
                    continue
                bs = a.get("byte_size")
                if isinstance(bs, int):
                    used += bs
            # estimate current screenshot size (small deterministic placeholder)
            est_size = 120000 if raw else 80000
            if used + est_size > lim:
                # still log failed invocation
                inv_id = _new_id("pws_call")
                inv_row = {
                    "id": inv_id,
                    "session_id": session_id,
                    "tab_id": tab_id,
                    "tool_name": "browser_take_screenshot",
                    "input": {"raw": raw, **({} if filename is None else {"filename": filename}), **({} if element is None else {"element": element, "ref": ref})},
                    "status": "failed",
                    "started_at": created,
                    "ended_at": created,
                    "duration_ms": int(max(0, (time.time() - t0) * 1000)),
                    "error_message": "quota exceeded: daily_artifact_bytes_limit",
                    "result": None,
                    "created_at": created,
                    "updated_at": created,
                }
                invocations.append(inv_row)
                _save("tool_invocations.json", invocations)
                return _err("QUOTA_EXCEEDED", "daily_artifact_bytes_limit exceeded.", limit=lim, used=used)

    # If element/ref is provided, try to validate against latest accessibility snapshot refs.
    # IMPORTANT: be tolerant—if snapshot is missing or refs cannot be parsed, accept and proceed (real servers can screenshot by selector even without snapshot).
    if ref is not None:
        snap = None
        obs_rows = [o for o in observations if isinstance(o, dict) and o.get("session_id") == session_id and o.get("tab_id") == tab_id and o.get("kind") == "accessibility_snapshot" and o.get("status") == "recorded"]
        obs_rows.sort(key=lambda o: (_parse_dt(o.get("occurred_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
                                     _parse_dt(o.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)))
        if obs_rows:
            snap = obs_rows[-1]
        if snap:
            payload = snap.get("payload") if isinstance(snap.get("payload"), dict) else {}
            refs = payload.get("refs")
            ref_ok = True
            if isinstance(refs, dict):
                # may be mapping {ref: ...}
                ref_ok = (ref in refs)
            elif isinstance(refs, list):
                ref_ok = (ref in refs)
            else:
                # unknown shape; don't hard fail
                ref_ok = True
            if not ref_ok:
                # Here we do reject: business rule says element/ref must correspond to latest snapshot refs.
                inv_id = _new_id("pws_call")
                inv_row = {
                    "id": inv_id,
                    "session_id": session_id,
                    "tab_id": tab_id,
                    "tool_name": "browser_take_screenshot",
                    "input": {"raw": raw, **({} if filename is None else {"filename": filename}), "element": element, "ref": ref},
                    "status": "failed",
                    "started_at": created,
                    "ended_at": created,
                    "duration_ms": int(max(0, (time.time() - t0) * 1000)),
                    "error_message": f"element/ref not found in latest accessibility snapshot (ref={ref})",
                    "result": None,
                    "created_at": created,
                    "updated_at": created,
                }
                invocations.append(inv_row)
                _save("tool_invocations.json", invocations)
                sess["last_activity_at"] = created
                sess["updated_at"] = created
                _save("automation_sessions.json", sessions)
                return _err("NOT_FOUND", f"element/ref not found in latest accessibility snapshot (ref={ref})", reason="ref_not_in_snapshot")

    # Create tool invocation (succeeded) and artifact
    inv_id = _new_id("pws_call")
    tool_input = {"raw": raw}
    if filename is not None:
        tool_input["filename"] = filename
    if element is not None:
        tool_input["element"] = element
        tool_input["ref"] = ref

    # Determine artifact properties
    ext = "png" if raw else "jpeg"
    content_type = "image/png" if raw else "image/jpeg"
    artifact_type = "screenshot_png" if raw else "screenshot_jpeg"
    if not filename:
        filename = f"page-{created.replace(':','').replace('-','').replace('Z','')}.{ext}"

    # Generate deterministic placeholder bytes and store to local fs
    data = (f"pws_screenshot:{session_id}:{tab_id}:{created}:{ext}").encode("utf-8")
    blob = base64.b64encode(hashlib.sha256(data).digest())  # not real image, but stable bytes
    byte_size = len(blob)
    sha256 = hashlib.sha256(blob).hexdigest()

    storage_dir = os.path.join(_DB, "artifacts_store")
    try:
        os.makedirs(storage_dir, exist_ok=True)
    except Exception:
        # If cannot create dir, proceed with memory backend
        storage_dir = None

    if storage_dir:
        safe_name = filename.replace("/", "_")
        path = os.path.join(storage_dir, f"{inv_id}_{safe_name}")
        try:
            with open(path, "wb") as f:
                f.write(blob)
            storage_backend = "local_fs"
            storage_uri = path
        except Exception:
            storage_backend = "memory"
            storage_uri = f"memory://{inv_id}/{safe_name}"
    else:
        storage_backend = "memory"
        storage_uri = f"memory://{inv_id}/{filename.replace('/','_')}"

    inv_row = {
        "id": inv_id,
        "session_id": session_id,
        "tab_id": tab_id,
        "tool_name": "browser_take_screenshot",
        "input": tool_input,
        "status": "succeeded",
        "started_at": created,
        "ended_at": created,
        "duration_ms": int(max(0, (time.time() - t0) * 1000)),
        "error_message": None,
        "result": {"artifact_type": artifact_type, "filename": filename, "content_type": content_type, "byte_size": byte_size, "storage_backend": storage_backend, "storage_uri": storage_uri, "sha256": sha256},
        "created_at": created,
        "updated_at": created,
    }
    invocations.append(inv_row)

    art_id = _new_id("pws_art")
    art_row = {
        "id": art_id,
        "session_id": session_id,
        "tab_id": tab_id,
        "invocation_id": inv_id,
        "artifact_type": artifact_type,
        "filename": filename,
        "content_type": content_type,
        "byte_size": byte_size,
        "storage_backend": storage_backend,
        "storage_uri": storage_uri,
        "sha256": sha256,
        "status": "available",
        "created_at": created,
        "updated_at": created,
    }
    artifacts.append(art_row)

    sess["last_activity_at"] = created
    sess["updated_at"] = created
    if key_row is not None:
        key_row["last_used_at"] = created
        key_row["updated_at"] = created

    _save("automation_sessions.json", sessions)
    _save("client_keys.json", keys)
    _save("tool_invocations.json", invocations)
    _save("artifacts.json", artifacts)
    return {"invocation": inv_row, "artifact": art_row}

def browser_snapshot(**_extra):
    import json, os, datetime, hashlib, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    invs = _load("tool_invocations.json")
    obs = _load("page_observations.json")
    keys = _load("client_keys.json")

    def _parse_iso(dt):
        if dt is None:
            return None
        try:
            return datetime.datetime.fromisoformat(dt)
        except Exception:
            return None

    def _today_key_window():
        start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _key_for_session(session):
        cid = session.get("client_key_id")
        if not cid:
            return None
        return next((k for k in keys if k.get("id") == cid), None)

    def _enforce_key_limits(session):
        k = _key_for_session(session)
        if not k:
            return None
        if k.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")
        day_start, day_end = _today_key_window()
        key_id = k.get("id")
        lim_i = k.get("daily_invocation_limit")
        if isinstance(lim_i, int):
            cnt = 0
            for inv in invs:
                sid = inv.get("session_id")
                srow = next((s for s in sessions if s.get("id") == sid), None)
                if not srow or srow.get("client_key_id") != key_id:
                    continue
                ca = _parse_iso(inv.get("created_at"))
                if ca and day_start <= ca < day_end:
                    cnt += 1
            if cnt >= lim_i:
                return _err("QUOTA_EXCEEDED", "Daily invocation limit exceeded", limit=lim_i)
        return None

    def _record_invocation(session_id, tab_id, status, result=None, error_message=None):
        inv_id = "inv_" + hashlib.sha256((str(now.timestamp()) + ":" + str(random.random())).encode("utf-8")).hexdigest()[:24]
        started = now_iso
        ended = now_iso
        row = {
            "id": inv_id,
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_snapshot",
            "input": {},
            "status": status,
            "started_at": started,
            "ended_at": ended,
            "duration_ms": 0,
            "error_message": error_message,
            "result": result,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invs.append(row)
        return row

    def _choose_session():
        best = None
        for s in sessions:
            if s.get("status") != "active":
                continue
            tab_id = s.get("current_tab_id")
            if tab_id:
                trow = next((t for t in tabs if t.get("id") == tab_id and t.get("session_id") == s.get("id")), None)
                if trow and trow.get("status") == "open":
                    return s, trow
            if best is None:
                trow = next((t for t in tabs if t.get("session_id") == s.get("id") and t.get("status") == "open"), None)
                if trow:
                    best = (s, trow)
        if best:
            return best
        for s in sessions:
            if s.get("status") == "active":
                return s, None
        return None, None

    session, tab = _choose_session()
    if not session:
        return _err("UNAUTHORIZED", "No accessible session context")
    qerr = _enforce_key_limits(session)
    if qerr:
        _record_invocation(session.get("id"), (tab or {}).get("id"), "failed", error_message=qerr["error"]["message"])
        _save("tool_invocations.json", invs)
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        return qerr

    if not tab or not tab.get("id"):
        _record_invocation(session.get("id"), None, "failed", error_message="no active tab")
        _save("tool_invocations.json", invs)
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        return _err("NOT_FOUND", "no active tab")

    if tab.get("status") != "open":
        _record_invocation(session.get("id"), tab.get("id"), "failed", error_message="tab is not open")
        _save("tool_invocations.json", invs)
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        return _err("CONFLICT", "tab is not open")

    inv = _record_invocation(session.get("id"), tab.get("id"), "succeeded", result=None, error_message=None)
    _save("tool_invocations.json", invs)

    # Create snapshot observation with refs
    snap_id = "obs_" + hashlib.sha256((inv["id"] + ":snapshot").encode("utf-8")).hexdigest()[:24]
    # Deterministic pseudo refs map based on tab url/title
    seed = (tab.get("current_url") or "") + "|" + (tab.get("title") or "") + "|" + tab.get("id")
    base = hashlib.sha256(seed.encode("utf-8")).hexdigest()
    refs = {}
    for i in range(1, 21):
        r = f"ref_{base[:8]}_{i}"
        refs[r] = {"hint": f"node_{i}", "role": "generic"}
    tree = {"role": "document", "name": tab.get("title"), "children": [{"ref": k} for k in list(refs.keys())[:10]]}

    payload = {
        "tree": tree,
        "refs": refs,
        "activeUrl": tab.get("current_url"),
        "title": tab.get("title"),
    }

    o = {
        "id": snap_id,
        "session_id": session.get("id"),
        "tab_id": tab.get("id"),
        "invocation_id": inv.get("id"),
        "kind": "accessibility_snapshot",
        "occurred_at": now_iso,
        "payload": payload,
        "status": "recorded",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    obs.append(o)
    _save("page_observations.json", obs)

    inv["result"] = {"snapshot_observation_id": snap_id, "refs_count": len(refs)}
    inv["updated_at"] = now_iso
    _save("tool_invocations.json", invs)

    session["last_activity_at"] = now_iso
    session["updated_at"] = now_iso
    _save("automation_sessions.json", sessions)
    k = _key_for_session(session)
    if k:
        k["last_used_at"] = now_iso
        k["updated_at"] = now_iso
        _save("client_keys.json", keys)

    return payload

def browser_click(element, ref, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _today_key(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _log_invocation(invocations, session_id, tab_id, status, inp, result=None, error_message=None):
        created = _iso(now)
        inv_id = _new_id("pws_call")
        inv_row = {
            "id": inv_id,
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_click",
            "input": inp,
            "status": status,
            "started_at": created,
            "ended_at": created,
            "duration_ms": int(max(0, (time.time() - t0) * 1000)),
            "error_message": error_message,
            "result": result,
            "created_at": created,
            "updated_at": created,
        }
        invocations.append(inv_row)
        return inv_row

    # Validate inputs (schema)
    if not isinstance(element, str) or not element.strip():
        return _err("VALIDATION_ERROR", "element must be a non-empty string.")
    if not isinstance(ref, str) or not ref.strip():
        return _err("VALIDATION_ERROR", "ref must be a non-empty string.")

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    invocations = _load("tool_invocations.json")
    observations = _load("page_observations.json")
    keys = _load("client_keys.json")

    # Resolve an authorized (active key if present) session+current open tab combination
    uses_keys = bool(keys) or any(isinstance(s, dict) and s.get("client_key_id") for s in sessions)

    active_key_ids = set()
    if uses_keys:
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str):
                active_key_ids.add(k["id"])

    sess = None
    tab = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("status") not in ("active",):  # tool operates on active session
            continue
        if uses_keys and s.get("client_key_id") and s.get("client_key_id") not in active_key_ids:
            continue
        ctid = s.get("current_tab_id")
        if not isinstance(ctid, str) or not ctid:
            continue
        t = next((x for x in tabs if isinstance(x, dict) and x.get("id") == ctid and x.get("session_id") == s.get("id")), None)
        if t and t.get("status") == "open":
            sess, tab = s, t
            break

    inp = {"element": element, "ref": ref}

    if not sess or not tab:
        # Must log every call
        inv = _log_invocation(invocations, sess.get("id") if sess else "", tab.get("id") if tab else None, "failed", inp, result=None, error_message="no active tab")
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No active tab in the current session.", reason="no_active_tab", invocation_id=inv["id"])

    # Enforce daily invocation limit for key-owned sessions
    if uses_keys and sess.get("client_key_id"):
        key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == sess.get("client_key_id")), None)
        if not key_row or key_row.get("status") != "active":
            inv = _log_invocation(invocations, sess.get("id"), tab.get("id"), "failed", inp, result=None, error_message="client key disabled/revoked")
            _save("tool_invocations.json", invocations)
            return _err("UNAUTHORIZED", "Client key is disabled or revoked.")
        limit = key_row.get("daily_invocation_limit")
        if isinstance(limit, int):
            day = _today_key(now)
            used = 0
            for r in invocations:
                if not isinstance(r, dict):
                    continue
                if r.get("session_id") != sess.get("id"):
                    continue
                ca = _parse_dt(r.get("created_at"))
                if ca and _today_key(ca) == day:
                    used += 1
            if used >= limit:
                inv = _log_invocation(invocations, sess.get("id"), tab.get("id"), "failed", inp, result=None, error_message="quota exceeded: daily invocation limit")
                _save("tool_invocations.json", invocations)
                return _err("QUOTA_EXCEEDED", "Daily invocation limit exceeded.", limit=limit)

        # Update last_used_at
        key_row["last_used_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("client_keys.json", keys)

    # Resolve ref against latest accessibility snapshot for this tab IF one exists.
    # Real behavior must accept valid requests consistent with data: if no snapshot exists, do not block.
    latest_snap = None
    latest_snap_dt = None
    for ob in observations:
        if not isinstance(ob, dict):
            continue
        if ob.get("session_id") != sess.get("id") or ob.get("tab_id") != tab.get("id"):
            continue
        if ob.get("status") == "deleted":
            continue
        if ob.get("kind") != "accessibility_snapshot":
            continue
        odt = _parse_dt(ob.get("occurred_at")) or _parse_dt(ob.get("created_at")) or _parse_dt(ob.get("updated_at"))
        if odt and (latest_snap_dt is None or odt > latest_snap_dt):
            latest_snap_dt = odt
            latest_snap = ob

    if latest_snap is not None:
        payload = latest_snap.get("payload") if isinstance(latest_snap.get("payload"), dict) else {}
        refs = payload.get("refs")
        # Snapshot schema says payload contains refs; allow either dict or list.
        found = False
        if isinstance(refs, dict):
            found = ref in refs
        elif isinstance(refs, list):
            found = ref in refs
        elif refs is None:
            # If refs missing, treat as non-authoritative snapshot rather than hard fail.
            found = True
        else:
            found = True
        if not found:
            inv = _log_invocation(invocations, sess.get("id"), tab.get("id"), "failed", inp, result=None,
                                  error_message=f"element/ref not found in latest accessibility snapshot (ref={ref})")
            _save("tool_invocations.json", invocations)
            sess["last_activity_at"] = _iso(now)
            sess["updated_at"] = _iso(now)
            _save("automation_sessions.json", sessions)
            return _err("NOT_FOUND", f"element/ref not found in latest accessibility snapshot (ref={ref})", reason="ref_not_in_snapshot", invocation_id=inv["id"])

    # Persist invocation success, update session activity
    inv = _log_invocation(invocations, sess.get("id"), tab.get("id"), "succeeded", inp, result={"clicked": True}, error_message=None)
    _save("tool_invocations.json", invocations)

    sess["last_activity_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    _save("automation_sessions.json", sessions)

    return {"invocation": inv, "session_id": sess.get("id"), "tab_id": tab.get("id"), "result": inv.get("result")}

