        if ob.get("kind") != "accessibility_snapshot":
            continue
        odt = _parse_dt(ob.get("occurred_at")) or _parse_dt(ob.get("created_at")) or _parse_dt(ob.get("updated_at"))
        if odt and (latest_snap_dt is None or odt > latest_snap_dt):
            latest_snap_dt = odt
            latest_snap = ob

    if latest_snap is not None:
        payload = latest_snap.get("payload") if isinstance(latest_snap.get("payload"), dict) else {}
        refs = payload.get("refs")
        found = False
        if isinstance(refs, dict):
            found = ref in refs
        elif isinstance(refs, list):
            found = ref in refs
        elif refs is None:
            found = True
        else:
            found = True
        if not found:
            inv = _log_invocation(invocations, sess.get("id"), tab.get("id"), "failed", inp, result=None,
                                  error_message=f"element/ref not found in latest accessibility snapshot (ref={ref})")
            _save("tool_invocations.json", invocations)
            sess["last_activity_at"] = _iso(now)
            sess["updated_at"] = _iso(now)
            _save("automation_sessions.json", sessions)
            return _err("NOT_FOUND", f"element/ref not found in latest accessibility snapshot (ref={ref})", reason="ref_not_in_snapshot", invocation_id=inv["id"])

    inv = _log_invocation(invocations, sess.get("id"), tab.get("id"), "succeeded", inp, result={"selected": values}, error_message=None)
    _save("tool_invocations.json", invocations)

    sess["last_activity_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    _save("automation_sessions.json", sessions)

    return {"invocation": inv, "session_id": sess.get("id"), "tab_id": tab.get("id"), "result": inv.get("result")}

def browser_tab_list(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    day = now[:10]

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    invocations = _load("tool_invocations.json")
    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    client_keys = _load("client_keys.json")

    def _log(status, session_id=None, tab_id=None, input_obj=None, result=None, error_message=None):
        inv_id = _new_id("inv")
        started_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ended_at = started_at
        duration_ms = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": inv_id,
            "session_id": session_id if session_id is not None else "",
            "tab_id": tab_id,
            "tool_name": "browser_tab_list",
            "input": input_obj if input_obj is not None else {},
            "status": status,
            "started_at": started_at,
            "ended_at": ended_at,
            "duration_ms": duration_ms,
            "error_message": error_message,
            "result": result,
            "created_at": now,
            "updated_at": now
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row

    def _active_key_for_session(sess):
        ckid = sess.get("client_key_id")
        if not ckid:
            return None
        for k in client_keys:
            if k.get("id") == ckid:
                return k
        return None

    def _count_today_tool_calls_for_key(key_id):
        # Determine by joining invocations->session->client_key_id
        sid_to_ck = {s.get("id"): s.get("client_key_id") for s in sessions if s.get("id")}
        return sum(1 for r in invocations if r.get("tool_name") and r.get("created_at", "")[:10] == day and sid_to_ck.get(r.get("session_id")) == key_id)

    # Resolve a session that can serve list (active-ish); if multi-tenant, prefer a session with an active key
    candidate = None
    candidate_key = None
    for s in sessions:
        if s.get("status") not in ("active", "closing", "errored"):
            continue
        k = _active_key_for_session(s)
        if k and k.get("status") == "active":
            candidate = s
            candidate_key = k
            break
    if not candidate:
        for s in sessions:
            if s.get("status") in ("active", "closing", "errored"):
                candidate = s
                candidate_key = _active_key_for_session(s)
                break

    if not candidate:
        _log("failed", session_id="", tab_id=None, input_obj={}, error_message="no active session")
        return _err("NOT_FOUND", "no active session")

    # Key enforcement if session is keyed
    if candidate_key:
        if candidate_key.get("status") != "active":
            _log("failed", session_id=candidate["id"], tab_id=None, input_obj={}, error_message="client key not active")
            return _err("UNAUTHORIZED", "client key is not active")
        lim = candidate_key.get("daily_invocation_limit")
        if isinstance(lim, int) and lim >= 0:
            used = _count_today_tool_calls_for_key(candidate_key["id"])
            if used >= lim:
                _log("failed", session_id=candidate["id"], tab_id=None, input_obj={}, error_message="daily invocation quota exceeded")
                return _err("QUOTA_EXCEEDED", "daily invocation quota exceeded", limit=lim, used=used)

    # List tabs (open/closing) ordered by tab_index
    out = [t for t in tabs if t.get("session_id") == candidate.get("id") and t.get("status") in ("open", "closing")]
    out.sort(key=lambda r: (r.get("tab_index") if isinstance(r.get("tab_index"), int) else 10**18, r.get("id", "")))

    result = {"tabs": out, "count": len(out)}
    inv = _log("succeeded", session_id=candidate["id"], tab_id=None, input_obj={}, result=result)

    # Update session activity + key last_used
    candidate["last_activity_at"] = now
    candidate["updated_at"] = now
    _save("automation_sessions.json", sessions)
    if candidate_key:
        candidate_key["last_used_at"] = now
        candidate_key["updated_at"] = now
        _save("client_keys.json", client_keys)

    return {"invocation": inv, "tabs": out, "count": len(out)}

def browser_tab_select(index, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    invocations = _load("tool_invocations.json")
    keys = _load("client_keys.json")

    def _log(session_id, tab_id, input_obj, status, result=None, error_message=None):
        inv_id = "inv_" + uuid.uuid4().hex
        row = {
            "id": inv_id,
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_tab_select",
            "input": input_obj,
            "status": status,
            "started_at": now_iso,
            "ended_at": now_iso,
            "duration_ms": 0,
            "error_message": error_message,
            "result": result,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        return row

    def _pick_session():
        candidates = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
        if not candidates:
            return None
        usable = []
        for s in candidates:
            kid = s.get("client_key_id")
            if kid is None:
                usable.append(s)
                continue
            k = next((kk for kk in keys if kk.get("id") == kid), None)
            if k and k.get("status") == "active":
                usable.append(s)
        return usable[0] if usable else None

    def _enforce_invocation_quota(session_row):
        kid = session_row.get("client_key_id")
        if kid is None:
            return None
        k = next((kk for kk in keys if kk.get("id") == kid), None)
        if not k:
            return _err("UNAUTHORIZED", "client key not found for session")
        if k.get("status") != "active":
            return _err("UNAUTHORIZED", "client key is not active")
        lim = k.get("daily_invocation_limit")
        if isinstance(lim, int):
            start_day = now.replace(hour=0, minute=0, second=0, microsecond=0)
            start_iso = start_day.isoformat()
            key_session_ids = {s.get("id") for s in sessions if s.get("client_key_id") == kid}
            count = 0
            for inv in invocations:
                if inv.get("session_id") in key_session_ids:
                    ca = inv.get("created_at")
                    if isinstance(ca, str) and ca >= start_iso:
                        count += 1
            if count >= lim:
                return _err("QUOTA_EXCEEDED", "daily invocation limit exceeded", limit=lim)
        k["last_used_at"] = now_iso
        k["updated_at"] = now_iso
        _save("client_keys.json", keys)
        return None

    # validate index per tool constraint: required and index >=0 integer-like
    if not isinstance(index, (int, float)) or isinstance(index, bool):
        sess = _pick_session()
        if sess:
            _enforce_invocation_quota(sess)
            _log(sess["id"], None, {"index": index}, "failed", error_message="index must be a number")
            sess["last_activity_at"] = now_iso
            sess["updated_at"] = now_iso
            _save("automation_sessions.json", sessions)
            _save("tool_invocations.json", invocations)
        return _err("VALIDATION_ERROR", "index must be a number")
    if int(index) != index or index < 0:
        sess = _pick_session()
        if sess:
            _enforce_invocation_quota(sess)
            _log(sess["id"], None, {"index": index}, "failed", error_message="index must be a non-negative integer")
            sess["last_activity_at"] = now_iso
            sess["updated_at"] = now_iso
            _save("automation_sessions.json", sessions)
            _save("tool_invocations.json", invocations)
        return _err("VALIDATION_ERROR", "index must be a non-negative integer")
    index = int(index)

    session = _pick_session()
    if not session:
        return _err("NOT_FOUND", "no active session")

    quota_err = _enforce_invocation_quota(session)
    if quota_err:
        _log(session["id"], None, {"index": index}, "failed", error_message=quota_err["error"]["message"])
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        _save("tool_invocations.json", invocations)
        return quota_err

    sid = session["id"]
    target = next((t for t in tabs if t.get("session_id") == sid and t.get("tab_index") == index), None)
    if not target:
        inv = _log(sid, None, {"index": index}, "failed", error_message="tab index not found")
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "tab index does not exist", invocation_id=inv["id"])

    if target.get("status") != "open":
        inv = _log(sid, target.get("id"), {"index": index}, "failed", error_message="tab is not open")
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "tab is not open", tab_status=target.get("status"), invocation_id=inv["id"])

    session["current_tab_id"] = target["id"]
    session["last_activity_at"] = now_iso
    session["updated_at"] = now_iso

    inv = _log(sid, target["id"], {"index": index}, "succeeded", result={"tab": target})
    _save("automation_sessions.json", sessions)
    _save("tool_invocations.json", invocations)

    return {
        "tab": target,
        "session": {"id": sid, "current_tab_id": session.get("current_tab_id")},
        "invocation": {"id": inv["id"], "status": inv["status"]},
    }

