            "started_at": now_iso,
            "ended_at": now_iso,
            "duration_ms": 0,
            "error_message": error_message,
            "result": result,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        return row

    def _pick_session():
        candidates = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
        if not candidates:
            return None
        usable = []
        for s in candidates:
            kid = s.get("client_key_id")
            if kid is None:
                usable.append(s)
                continue
            k = next((kk for kk in keys if kk.get("id") == kid), None)
            if k and k.get("status") == "active":
                usable.append(s)
        return usable[0] if usable else None

    def _enforce_invocation_quota(session_row):
        kid = session_row.get("client_key_id")
        if kid is None:
            return None
        k = next((kk for kk in keys if kk.get("id") == kid), None)
        if not k:
            return _err("UNAUTHORIZED", "client key not found for session")
        if k.get("status") != "active":
            return _err("UNAUTHORIZED", "client key is not active")
        lim = k.get("daily_invocation_limit")
        if isinstance(lim, int):
            start_day = now.replace(hour=0, minute=0, second=0, microsecond=0)
            start_iso = start_day.isoformat()
            key_session_ids = {s.get("id") for s in sessions if s.get("client_key_id") == kid}
            count = 0
            for inv in invocations:
                if inv.get("session_id") in key_session_ids:
                    ca = inv.get("created_at")
                    if isinstance(ca, str) and ca >= start_iso:
                        count += 1
            if count >= lim:
                return _err("QUOTA_EXCEEDED", "daily invocation limit exceeded", limit=lim)
        k["last_used_at"] = now_iso
        k["updated_at"] = now_iso
        _save("client_keys.json", keys)
        return None

    def _tab_list_for_session(sid):
        lst = [t for t in tabs if t.get("session_id") == sid and t.get("status") in ("open", "closing")]
        lst.sort(key=lambda r: r.get("tab_index", 0))
        return lst

    # Validate index if provided
    input_obj = {}
    if index is not None:
        input_obj["index"] = index
        if not isinstance(index, (int, float)) or isinstance(index, bool):
            sess = _pick_session()
            if sess:
                _enforce_invocation_quota(sess)
                inv = _log(sess["id"], None, input_obj, "failed", error_message="index must be a number")
                sess["last_activity_at"] = now_iso
                sess["updated_at"] = now_iso
                _save("automation_sessions.json", sessions)
                _save("tool_invocations.json", invocations)
                return _err("VALIDATION_ERROR", "index must be a number", invocation_id=inv["id"])
            return _err("VALIDATION_ERROR", "index must be a number")
        if int(index) != index or index < 0:
            sess = _pick_session()
            if sess:
                _enforce_invocation_quota(sess)
                inv = _log(sess["id"], None, input_obj, "failed", error_message="index must be a non-negative integer")
                sess["last_activity_at"] = now_iso
                sess["updated_at"] = now_iso
                _save("automation_sessions.json", sessions)
                _save("tool_invocations.json", invocations)
                return _err("VALIDATION_ERROR", "index must be a non-negative integer", invocation_id=inv["id"])
            return _err("VALIDATION_ERROR", "index must be a non-negative integer")
        index = int(index)

    session = _pick_session()
    if not session:
        return _err("NOT_FOUND", "no active session")

    quota_err = _enforce_invocation_quota(session)
    if quota_err:
        inv = _log(session["id"], None, input_obj, "failed", error_message=quota_err["error"]["message"])
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        _save("tool_invocations.json", invocations)
        return quota_err

    sid = session["id"]

    # Determine target tab
    target = None
    if index is not None:
        target = next((t for t in tabs if t.get("session_id") == sid and t.get("tab_index") == index), None)
        if not target:
            inv = _log(sid, None, input_obj, "failed", error_message="tab index not found")
            session["last_activity_at"] = now_iso
            session["updated_at"] = now_iso
            _save("automation_sessions.json", sessions)
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "tab index does not exist", invocation_id=inv["id"])
    else:
        ct = session.get("current_tab_id")
        if ct is None:
            inv = _log(sid, None, input_obj, "failed", error_message="no active tab")
            session["last_activity_at"] = now_iso
            session["updated_at"] = now_iso
            _save("automation_sessions.json", sessions)
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "no active tab", invocation_id=inv["id"])
        target = next((t for t in tabs if t.get("session_id") == sid and t.get("id") == ct), None)
        if not target:
            inv = _log(sid, None, input_obj, "failed", error_message="current tab not found")
            session["current_tab_id"] = None
            session["last_activity_at"] = now_iso
            session["updated_at"] = now_iso
            _save("automation_sessions.json", sessions)
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "current tab not found", invocation_id=inv["id"])

    # Transition open->closing->closed (apply both to make it immediately closed)
    st = target.get("status")
    if st in ("closed",):
        inv = _log(sid, target.get("id"), input_obj, "failed", error_message="tab already closed")
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "tab is already closed", tab_status=st, invocation_id=inv["id"])
    if st not in ("open", "closing", "crashed"):
        inv = _log(sid, target.get("id"), input_obj, "failed", error_message="tab cannot be closed from current state")
        session["last_activity_at"] = now_iso
        session["updated_at"] = now_iso
        _save("automation_sessions.json", sessions)
        _save("tool_invocations.json", invocations)
        return _err("INVALID_TRANSITION", "tab cannot be closed from current state", tab_status=st, invocation_id=inv["id"])

    # Apply lifecycle transitions respecting schema
    if st == "open":
        target["status"] = "closing"
        target["updated_at"] = now_iso
    # closing or crashed -> closed
    target["status"] = "closed"
    target["closed_at"] = now_iso
    target["updated_at"] = now_iso

    # If closed current tab, update current_tab_id
    if session.get("current_tab_id") == target.get("id"):
        remaining = [t for t in tabs if t.get("session_id") == sid and t.get("status") == "open"]
        remaining.sort(key=lambda r: r.get("tab_index", 0))
        session["current_tab_id"] = remaining[0]["id"] if remaining else None

    session["last_activity_at"] = now_iso
    session["updated_at"] = now_iso

    tab_list = _tab_list_for_session(sid)
    inv = _log(sid, target.get("id"), input_obj, "succeeded", result={"tabs": tab_list, "closed_tab_id": target.get("id")})
    _save("browser_tabs.json", tabs)
    _save("automation_sessions.json", sessions)
    _save("tool_invocations.json", invocations)

    return {
        "closed_tab": target,
        "tabs": tab_list,
        "session": {"id": sid, "current_tab_id": session.get("current_tab_id")},
        "invocation": {"id": inv["id"], "status": inv["status"]},
    }

def browser_generate_playwright_test(name, description, steps, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat()

    # ---- helpers ----
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            # support Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _day_bounds(dt):
        # server timezone: use UTC for deterministic offline behavior
        d0 = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=dt.tzinfo)
        d1 = d0 + datetime.timedelta(days=1)
        return d0, d1

    def _gen_id(prefix, existing_ids):
        # collision-resistant enough for local store
        raw = f"{prefix}_{now_s}_{os.getpid()}_{time.time_ns()}"
        hid = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]
        cid = f"{prefix}_{hid}"
        if cid not in existing_ids:
            return cid
        i = 2
        while True:
            cid2 = f"{cid}_{i}"
            if cid2 not in existing_ids:
                return cid2
            i += 1

    def _record_invocation(tool_invocations, session_id, tab_id, input_payload, status, result=None, error_message=None, started_at=None, ended_at=None):
        existing_ids = {r.get("id") for r in tool_invocations if isinstance(r, dict)}
        inv_id = _gen_id("inv", existing_ids)
        if started_at is None:
            started_at = now
        if ended_at is None:
            ended_at = now
        dur = int(max(0, (ended_at - started_at).total_seconds() * 1000))
        row = {
            "id": inv_id,
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_generate_playwright_test",
            "input": input_payload,
            "status": status,
            "started_at": started_at.isoformat(),
            "ended_at": ended_at.isoformat(),
            "duration_ms": dur,
            "error_message": error_message,
            "result": result,
            "created_at": now_s,
            "updated_at": now_s,
        }
        tool_invocations.append(row)
        return inv_id

    def _sanitize_filename_component(s):
        s = s.strip()
        s = re.sub(r"\s+", "-", s)
        s = re.sub(r"[^A-Za-z0-9._-]+", "", s)
        if not s:
            return "test"
        return s[:80]

    def _ts_compact(dt):
        return dt.strftime("%Y%m%d-%H%M%S")

    def _escape_js_template(s):
        # safest simple string literal for TS: JSON dumps
        return json.dumps(s)

    # ---- validate inputs ----
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string", field="name")
    if not isinstance(description, str) or not description.strip():
        return _err("VALIDATION_ERROR", "description is required and must be a non-empty string", field="description")
    if not isinstance(steps, list) or len(steps) < 1:
        return _err("VALIDATION_ERROR", "steps is required and must be a non-empty array of strings", field="steps")
    for i, st in enumerate(steps):
        if not isinstance(st, str) or not st.strip():
            return _err("VALIDATION_ERROR", "each steps[i] must be a non-empty string", field="steps", index=i)

    # ---- load datastore ----
    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    tool_invocations = _load("tool_invocations.json")
    artifacts = _load("artifacts.json")
    client_keys = _load("client_keys.json")

    # ---- resolve authentication context (ambient) ----
    # Choose a working key+session combination. If there are active keys, enforce quotas against one that can serve.
    active_keys = [k for k in client_keys if isinstance(k, dict) and k.get("status") == "active"]
    any_keys_enabled = len(client_keys) > 0

    # Candidate sessions: active sessions preferred; any session ok for this tool (not tab/page scoped).
    def _session_ok(s):
        return isinstance(s, dict) and s.get("id") and s.get("status") in ("active", "closing", "errored", "closed")

    candidate_sessions = [s for s in sessions if _session_ok(s)]
    # Prefer active sessions
    candidate_sessions.sort(key=lambda s: 0 if s.get("status") == "active" else 1)

    # Determine a session_id/tab_id context for logging; for this tool tab_id is null.
    session_chosen = None
    key_chosen = None

    # quota accounting helpers (per key, per day)
    day0, day1 = _day_bounds(now)

    def _in_today(dt_s):
        dt = _parse_dt(dt_s)
        if dt is None:
            return False
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt >= day0) and (dt < day1)

    def _count_sessions_for_key(key_id):
        c = 0
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("client_key_id") != key_id:
                continue
            if _in_today(s.get("created_at")):
                c += 1
        return c

    def _count_invocations_for_key(key_id):
        # invocations don't store key id; infer via session.client_key_id
        sess_ids = {s.get("id") for s in sessions if isinstance(s, dict) and s.get("client_key_id") == key_id}
        c = 0
        for inv in tool_invocations:
            if not isinstance(inv, dict):
                continue
            if inv.get("session_id") in sess_ids and _in_today(inv.get("created_at")):
                c += 1
        return c

    def _sum_artifact_bytes_for_key(key_id):
        sess_ids = {s.get("id") for s in sessions if isinstance(s, dict) and s.get("client_key_id") == key_id}
        total = 0
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("session_id") in sess_ids and _in_today(a.get("created_at")):
                bs = a.get("byte_size")
                if isinstance(bs, int) and bs >= 0:
                    total += bs
        return total

    def _key_can_invoke(k, session_id):
        # key already active
        inv_limit = k.get("daily_invocation_limit")
        if inv_limit is not None:
            if not isinstance(inv_limit, int) or inv_limit < 0:
                # invalid stored config; treat as refusing service for this key
                return False, "invalid key invocation limit configuration"
            # this call counts as one invocation
            if _count_invocations_for_key(k.get("id")) + 1 > inv_limit:
                return False, "daily invocation quota exceeded"
        return True, None

    if any_keys_enabled:
        # Pick a session tied to an active key, or create context via any existing session for that key.
        # If no sessions exist, still authorize based on active key and use a synthetic "sessionless" logging? Not allowed by schema.
        # Therefore require at least one session to exist in store for operations in this multi-tenant mode.
        best = None
        for k in active_keys:
            kid = k.get("id")
            if not kid:
                continue
            # session must exist for logging
            key_sessions = [s for s in candidate_sessions if s.get("client_key_id") == kid]
            if not key_sessions:
                continue
            # choose first session for this key, but only if quota allows invocation
            for s in key_sessions:
                ok, _reason = _key_can_invoke(k, s.get("id"))
                if ok:
                    best = (k, s)
                    break
            if best:
                break
        if best is None:
            # Determine whether it's unauthorized (no active key+session) or quota exceeded (active key exists but capped)
            if not active_keys:
                return _err("UNAUTHORIZED", "no active client key available")
            # If there exists any active key with sessions but quota blocks, respond QUOTA_EXCEEDED
            quota_blocked = False
            for k in active_keys:
                kid = k.get("id")
                if not kid:
                    continue
                if any(s.get("client_key_id") == kid for s in candidate_sessions):
                    # test if blocked by invocation quota
                    inv_limit = k.get("daily_invocation_limit")
                    if isinstance(inv_limit, int):
                        if _count_invocations_for_key(kid) + 1 > inv_limit:
                            quota_blocked = True
                            break
            if quota_blocked:
                return _err("QUOTA_EXCEEDED", "test generation is rate-limited for your workspace")
            return _err("UNAUTHORIZED", "no authorized session/key combination found")
        key_chosen, session_chosen = best
    else:
        # Single-tenant: any existing session works; if none exist, cannot log invocation per schema.
        if not candidate_sessions:
            return _err("UNAUTHORIZED", "no automation session available to execute request")
        session_chosen = candidate_sessions[0]

    session_id = session_chosen.get("id")
    if not session_id:
        return _err("UNAUTHORIZED", "no valid session available")

    # ---- enforce key status (disabled/revoked must be rejected) ----
    if any_keys_enabled:
        # key_chosen is active by selection; still ensure status correct
        if not key_chosen or key_chosen.get("status") != "active":
            return _err("UNAUTHORIZED", "client key is not active")

    # ---- record invocation (running -> succeeded) ----
    input_payload = {"name": name, "description": description, "steps": steps}

    # Update session last_activity_at regardless of result (service dynamics)
    # (only if session isn't closed; still update updated_at)
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session_id:
            s["last_activity_at"] = now_s
            s["updated_at"] = now_s
            break

    started = datetime.datetime.now(datetime.timezone.utc)
    inv_id = _record_invocation(
        tool_invocations,
        session_id=session_id,
        tab_id=None,
        input_payload=input_payload,
        status="running",
        result=None,
        error_message=None,
        started_at=started,
        ended_at=None
    )
    _save("tool_invocations.json", tool_invocations)
    _save("automation_sessions.json", sessions)

    # ---- generate content ----
    # Minimal deterministic TS test snippet
    safe_title = name.strip()
    safe_desc = description.strip()
    lines = []
    lines.append("import { test, expect } from '@playwright/test';")
    lines.append("")
    lines.append(f"test({_escape_js_template(safe_title)}, async ({{ page }}) => {{")
    lines.append(f"  // {safe_desc}")
    lines.append("")
    for i, st in enumerate(steps, start=1):
        stc = st.strip()
        lines.append(f"  // Step {i}: {stc}")
        lines.append("  // TODO: implement")
        lines.append("")
    lines.append("});")
    content = "\n".join(lines).rstrip() + "\n"

    # ---- store artifact ----
    existing_art_ids = {r.get("id") for r in artifacts if isinstance(r, dict)}
    art_id = _gen_id("art", existing_art_ids)

    filename = f"{_sanitize_filename_component(safe_title)}-{_ts_compact(now)}.spec.ts"
    storage_backend = "local_fs"
    artifacts_dir = os.path.join(_DB, "artifacts_store")
    os.makedirs(artifacts_dir, exist_ok=True)
    storage_uri = os.path.join(artifacts_dir, f"{art_id}-{filename}")

    try:
        with open(storage_uri, "w", encoding="utf-8") as f:
            f.write(content)
    except OSError as e:
        ended = datetime.datetime.now(datetime.timezone.utc)
        # Mark invocation failed and persist
        for inv in tool_invocations:
            if isinstance(inv, dict) and inv.get("id") == inv_id:
                inv["status"] = "failed"
                inv["ended_at"] = ended.isoformat()
                inv["duration_ms"] = int(max(0, (ended - started).total_seconds() * 1000))
                inv["error_message"] = f"failed to write artifact: {e}"
                inv["updated_at"] = ended.isoformat()
                break
        _save("tool_invocations.json", tool_invocations)
        return _err("CONFLICT", "could not persist generated test artifact", detail=str(e))

    byte_size = len(content.encode("utf-8"))
    sha256 = hashlib.sha256(content.encode("utf-8")).hexdigest()

    # Enforce artifact bytes quota (if enabled) BEFORE committing artifact row
    if any_keys_enabled and key_chosen and key_chosen.get("daily_artifact_bytes_limit") is not None:
        lim = key_chosen.get("daily_artifact_bytes_limit")
        if not isinstance(lim, int) or lim < 0:
            # invalid stored config => fail safe
            ended = datetime.datetime.now(datetime.timezone.utc)
            for inv in tool_invocations:
                if isinstance(inv, dict) and inv.get("id") == inv_id:
                    inv["status"] = "failed"
                    inv["ended_at"] = ended.isoformat()
                    inv["duration_ms"] = int(max(0, (ended - started).total_seconds() * 1000))
                    inv["error_message"] = "invalid daily_artifact_bytes_limit configuration"
                    inv["updated_at"] = ended.isoformat()
                    break
            _save("tool_invocations.json", tool_invocations)
            return _err("CONFLICT", "invalid quota configuration")
        used = _sum_artifact_bytes_for_key(key_chosen.get("id"))
        if used + byte_size > lim:
            # Do not keep the file (best-effort deletion)
            try:
                os.remove(storage_uri)
            except OSError:
                pass
            ended = datetime.datetime.now(datetime.timezone.utc)
            for inv in tool_invocations:
                if isinstance(inv, dict) and inv.get("id") == inv_id:
                    inv["status"] = "failed"
                    inv["ended_at"] = ended.isoformat()
                    inv["duration_ms"] = int(max(0, (ended - started).total_seconds() * 1000))
                    inv["error_message"] = "daily artifact bytes quota exceeded"
                    inv["updated_at"] = ended.isoformat()
                    break
            _save("tool_invocations.json", tool_invocations)
            return _err("QUOTA_EXCEEDED", "test generation is rate-limited for your workspace")

    artifact_row = {
        "id": art_id,
        "session_id": session_id,
        "tab_id": None,
        "invocation_id": inv_id,
        "artifact_type": "playwright_test",
        "filename": filename,
        "content_type": "text/plain",
        "byte_size": byte_size,
        "storage_backend": storage_backend,
        "storage_uri": storage_uri,
        "sha256": sha256,
        "status": "available",
        "created_at": now_s,
        "updated_at": now_s,
    }
    artifacts.append(artifact_row)
    _save("artifacts.json", artifacts)

    # ---- finalize invocation as succeeded + result payload ----
    ended = datetime.datetime.now(datetime.timezone.utc)
    result = {
        "artifact_id": art_id,
        "filename": filename,
        "content_type": artifact_row["content_type"],
        "byte_size": byte_size,
        "storage_uri": storage_uri,
        "source": content,
    }
    for inv in tool_invocations:
        if isinstance(inv, dict) and inv.get("id") == inv_id:
            inv["status"] = "succeeded"
            inv["ended_at"] = ended.isoformat()
            inv["duration_ms"] = int(max(0, (ended - started).total_seconds() * 1000))
            inv["result"] = {
                "artifact_id": art_id,
                "filename": filename,
                "byte_size": byte_size,
                "storage_uri": storage_uri
            }
            inv["updated_at"] = ended.isoformat()
            break

    # Update key last_used_at if applicable
    if any_keys_enabled and key_chosen and key_chosen.get("id"):
        kid = key_chosen.get("id")
        changed = False
        for k in client_keys:
            if isinstance(k, dict) and k.get("id") == kid:
                k["last_used_at"] = now_s
                k["updated_at"] = now_s
                changed = True
                break
        if changed:
            _save("client_keys.json", client_keys)

    _save("tool_invocations.json", tool_invocations)

    # envelope
    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "invocation_id": inv_id,
        "latency_ms": latency_ms,
        "artifact": {
            "id": art_id,
            "artifact_type": artifact_row["artifact_type"],
            "filename": filename,
            "content_type": artifact_row["content_type"],
            "byte_size": byte_size,
            "storage_backend": storage_backend,
            "storage_uri": storage_uri,
            "sha256": sha256,
            "status": artifact_row["status"],
            "created_at": artifact_row["created_at"],
        },
        "test_source": content,
    }

def browser_wait_for(time=None, text=None, textGone=None, **_extra):
    import json, os, datetime, time as _time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}"

    def _active_key_context():
        keys = _load("client_keys.json")
        for k in keys:
            if k.get("status") == "active":
                return k
        if keys:
            return None
        return {"id": None}

    def _start_invocation(tool_name, session_id, tab_id, input_payload):
        invs = _load("tool_invocations.json")
        now = _now()
        inv = {
            "id": _gen_id("inv"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": tool_name,
            "input": input_payload,
            "status": "running",
            "started_at": _iso(now),
            "ended_at": None,
            "duration_ms": None,
            "error_message": None,
            "result": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        invs.append(inv)
        _save("tool_invocations.json", invs)
        return inv

    def _finish_invocation(inv_id, status, result=None, error_message=None, started_at_iso=None):
        invs = _load("tool_invocations.json")
        now = _now()
        for inv in invs:
            if inv.get("id") == inv_id:
                # lifecycle transitions: running -> succeeded/failed/cancelled
                if inv.get("status") != "running":
                    return False
                inv["status"] = status
                inv["ended_at"] = _iso(now)
                inv["updated_at"] = _iso(now)
                inv["result"] = result
                inv["error_message"] = error_message
                st = _parse_dt(started_at_iso or inv.get("started_at"))
                if st is not None:
                    inv["duration_ms"] = max(0, int((now - st).total_seconds() * 1000))
                else:
                    inv["duration_ms"] = None
                _save("tool_invocations.json", invs)
                return True
        return False

    # Validate inputs
    if time is None and text is None and textGone is None:
        return _err("VALIDATION_ERROR", "One of time, text, or textGone must be provided.")
    if time is not None:
        if not isinstance(time, (int, float)) or isinstance(time, bool):
            return _err("VALIDATION_ERROR", "time must be a positive number (seconds).")
        if time <= 0:
            return _err("VALIDATION_ERROR", "time must be a positive number (seconds).")
    if text is not None and (not isinstance(text, str) or not text.strip()):
        return _err("VALIDATION_ERROR", "text must be a non-empty string when provided.")
    if textGone is not None and (not isinstance(textGone, str) or not textGone.strip()):
        return _err("VALIDATION_ERROR", "textGone must be a non-empty string when provided.")
    if (text is None or not str(text).strip()) and (textGone is None or not str(textGone).strip()) and time is None:
        return _err("VALIDATION_ERROR", "At least one of time, text, textGone must be valid and non-empty.")

    # Ambient auth resolution (pick a usable session+tab combination; UNAUTHORIZED only if impossible)
    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")

    # Prefer an active session with an open current tab
    chosen_session = None
    chosen_tab = None
    for s in sessions:
        if s.get("status") != "active":
            continue
        ct = s.get("current_tab_id")
        if not ct:
            continue
        t = next((tt for tt in tabs if tt.get("id") == ct and tt.get("session_id") == s.get("id")), None)
        if t and t.get("status") == "open":
            chosen_session = s
            chosen_tab = t
            break

    # Fallback: any active session with any open tab
    if chosen_session is None:
        for s in sessions:
            if s.get("status") != "active":
                continue
            t = next((tt for tt in sorted([x for x in tabs if x.get("session_id") == s.get("id")], key=lambda r: r.get("tab_index", 0))
                      if tt.get("status") == "open"), None)
            if t:
                chosen_session = s
                chosen_tab = t
                break

    # If we have active sessions but none with tabs, deterministic "no active tab" -> NOT_FOUND per tool description
    if chosen_session is None:
        # still log the attempted invocation if any session exists? We need session_id FK, so cannot.
        return _err("NOT_FOUND", "No active session/tab available to wait on.")
    if chosen_tab is None:
        # We can log invocation with session_id but no tab_id; however tool requires a page => deterministic error.
        inv = _start_invocation("browser_wait_for", chosen_session.get("id"), None, {"time": time, "text": text, "textGone": textGone})
        _finish_invocation(inv["id"], "failed", result=None, error_message="no active tab", started_at_iso=inv.get("started_at"))
        # update session last_activity
        now = _now()
        for s in sessions:
            if s.get("id") == chosen_session.get("id"):
                s["last_activity_at"] = _iso(now)
                s["updated_at"] = _iso(now)
                break
        _save("automation_sessions.json", sessions)
        return _err("NOT_FOUND", "no active tab")

    # Reject for tabs not open (business rule)
    if chosen_tab.get("status") != "open":
        inv = _start_invocation("browser_wait_for", chosen_session.get("id"), chosen_tab.get("id"), {"time": time, "text": text, "textGone": textGone})
        _finish_invocation(inv["id"], "failed", result=None, error_message="tab is not open", started_at_iso=inv.get("started_at"))
        return _err("INVALID_TRANSITION", "Navigation/wait actions require an open tab.", tab_status=chosen_tab.get("status"))

    # Enforce daily invocation quota if client keys enabled for this session
    key_ctx = None
    key_id = chosen_session.get("client_key_id")
    if key_id:
        keys = _load("client_keys.json")
        key_ctx = next((k for k in keys if k.get("id") == key_id), None)
        if not key_ctx:
            return _err("UNAUTHORIZED", "Session client key is missing/invalid.")
        if key_ctx.get("status") != "active":
            return _err("UNAUTHORIZED", "Client key is not active.")
        limit = key_ctx.get("daily_invocation_limit")
        if isinstance(limit, int):
            now = _now()
            start = datetime.datetime(now.year, now.month, now.day, tzinfo=now.tzinfo)
            invs = _load("tool_invocations.json")
            used = 0
            for inv in invs:
                sid = inv.get("session_id")
                if sid != chosen_session.get("id"):
                    continue
                # Count per key by joining sessions
                if chosen_session.get("client_key_id") != key_id:
                    continue
                ca = _parse_dt(inv.get("created_at"))
                if ca and ca >= start and ca <= now:
                    used += 1
            if used >= limit:
                inv = _start_invocation("browser_wait_for", chosen_session.get("id"), chosen_tab.get("id"), {"time": time, "text": text, "textGone": textGone})
                _finish_invocation(inv["id"], "failed", result={"used_today": used, "limit": limit}, error_message="daily invocation limit exceeded", started_at_iso=inv.get("started_at"))
                return _err("QUOTA_EXCEEDED", "Daily invocation limit exceeded.", used_today=used, limit=limit)

    # Create invocation (running)
    inv = _start_invocation("browser_wait_for", chosen_session.get("id"), chosen_tab.get("id"), {"time": time, "text": text, "textGone": textGone})

    # Simulated wait via event log observation; we do not fabricate browser state, only read observations.
    obs = _load("page_observations.json")
    start_dt = _parse_dt(inv.get("started_at")) or _now()
    deadline = None
    if time is not None:
        deadline = start_dt + datetime.timedelta(seconds=float(time))

    def _matches(o):
        if o.get("session_id") != chosen_session.get("id") or o.get("tab_id") != chosen_tab.get("id"):
            return False
        odt = _parse_dt(o.get("occurred_at")) or _parse_dt(o.get("created_at"))
        if odt is None:
            return False
        return odt >= start_dt

    matched = []
    for o in obs:
        if _matches(o):
            matched.append(o)
    matched.sort(key=lambda r: (_parse_dt(r.get("occurred_at")) or _now()))

    # Determine condition: if text specified, succeed if found in any console_message payload.text since start.
    condition = None
    details = {}
    if text is not None:
        needle = text.strip()
        for o in matched:
            if o.get("kind") == "console_message":
                payload = o.get("payload") or {}
                t = payload.get("text")
                if isinstance(t, str) and needle in t:
                    condition = "text"
                    details = {"matched_in": "console_message", "observation_id": o.get("id"), "occurred_at": o.get("occurred_at")}
                    break

    # For textGone: if we have any snapshot payload that includes "tree" serialized and it DOES NOT include the text, consider gone.
    if condition is None and textGone is not None:
        needle = textGone.strip()
        # We can only infer disappearance if we have at least one snapshot; treat last snapshot as current page text container.
        snaps = [o for o in matched if o.get("kind") == "accessibility_snapshot"]
        if snaps:
            last = snaps[-1]
            payload = last.get("payload") or {}
            tree = payload.get("tree")
            tree_s = json.dumps(tree, ensure_ascii=False) if tree is not None else ""
            if needle not in tree_s:
                condition = "textGone"
                details = {"matched_in": "accessibility_snapshot", "observation_id": last.get("id"), "occurred_at": last.get("occurred_at")}

    # If no condition met and time provided, we "waited" fixed duration (without sleeping long); mark as time_elapsed.
    if condition is None and deadline is not None:
        # small real sleep capped to keep offline responsive
        remaining = (deadline - _now()).total_seconds()
        if remaining > 0:
            _time.sleep(min(0.05, remaining))
        condition = "time"
        details = {"waited_seconds": float(time)}

    # If still none, fail (no observable fulfillment)
    if condition is None:
        _finish_invocation(inv["id"], "failed", result={"matched_events": 0}, error_message="condition not met", started_at_iso=inv.get("started_at"))
        # update last activity
        sessions = _load("automation_sessions.json")
        now = _now()
        for s in sessions:
            if s.get("id") == chosen_session.get("id"):
                s["last_activity_at"] = _iso(now)
                s["updated_at"] = _iso(now)
                break
        _save("automation_sessions.json", sessions)
        return _err("NOT_FOUND", "Wait condition not met.", condition=None)

    # Provide relevant event log changes since start (capped)
    cap = 200
    out_events = matched[-cap:]
    truncated = len(matched) > cap

    result = {
        "session_id": chosen_session.get("id"),
        "tab_id": chosen_tab.get("id"),
        "condition": condition,
        "details": details,
        "events": out_events,
        "truncated": truncated,
        "total_events": len(matched),
    }

    _finish_invocation(inv["id"], "succeeded", result=result, error_message=None, started_at_iso=inv.get("started_at"))

    # update session last activity
    sessions = _load("automation_sessions.json")
    now = _now()
    for s in sessions:
        if s.get("id") == chosen_session.get("id"):
            s["last_activity_at"] = _iso(now)
            s["updated_at"] = _iso(now)
            break
    _save("automation_sessions.json", sessions)

    # update key last_used_at if applicable
    if key_ctx and key_ctx.get("id"):
        keys = _load("client_keys.json")
        for k in keys:
            if k.get("id") == key_ctx.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("client_keys.json", keys)

    return {"data": result}

def automation_session_list(client_key=None, status=None, browser_engine=None, created_after=None, created_before=None, limit=None, page_token=None, include_closed=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}"

    def _start_invocation(session_id, input_payload, tab_id=None):
        invs = _load("tool_invocations.json")
        now = _now()
        inv = {
            "id": _gen_id("inv"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "automation_session_list",  # not in enum; still record to log calls without breaking store
            "input": input_payload,
            "status": "succeeded",
            "started_at": _iso(now),
            "ended_at": _iso(now),
            "duration_ms": 0,
            "error_message": None,
            "result": {"note": "list"},
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        invs.append(inv)
        _save("tool_invocations.json", invs)
        return inv

    # Validation
    if status is not None and status not in ("active", "closing", "closed", "errored"):
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if browser_engine is not None and browser_engine not in ("chromium", "firefox", "webkit"):
        return _err("VALIDATION_ERROR", "Invalid browser_engine filter.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if include_closed is None:
        include_closed = False
    if not isinstance(include_closed, bool):
        return _err("VALIDATION_ERROR", "include_closed must be a boolean.")
    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string.")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string.")
    if ca and cb and cb < ca:
        return _err("VALIDATION_ERROR", "created_before must be >= created_after.")

    keys = _load("client_keys.json")
    key_row = None
    if keys:
        # client keys enabled -> must authenticate explicit param
        if client_key is None or not isinstance(client_key, str) or not client_key.strip():
            return _err("UNAUTHORIZED", "client_key is required.")
        # Authenticate by matching id OR stored client-visible value; store only has id + hash, so id is usable.
        key_row = next((k for k in keys if k.get("id") == client_key.strip()), None)
        if not key_row:
            return _err("UNAUTHORIZED", "Invalid client_key.")
        if key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "Client key is disabled or revoked.")
        # update last_used_at
        now = _now()
        for k in keys:
            if k.get("id") == key_row.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("client_keys.json", keys)

    # Pagination token decode (opaque cursor over last_activity_at, id)
    cursor = None
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token:
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string.")
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "last_activity_at" not in obj or "id" not in obj:
                return _err("VALIDATION_ERROR", "Invalid page_token.")
            cursor = obj
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    sessions = _load("automation_sessions.json")

    # Apply visibility: if key enabled, only sessions matching key id
    if key_row:
        sessions = [s for s in sessions if s.get("client_key_id") == key_row.get("id")]

    # Filters
    out = []
    for s in sessions:
        if status is not None and s.get("status") != status:
            continue
        if not include_closed and s.get("status") == "closed" and status is None:
            continue
        if browser_engine is not None and s.get("browser_engine") != browser_engine:
            continue
        s_created = _parse_dt(s.get("created_at"))
        if ca and (s_created is None or s_created < ca):
            continue
        if cb and (s_created is None or s_created >= cb):
            continue
        out.append(s)

    # Sort by most recent activity desc, then id desc
    def _key(s):
        la = _parse_dt(s.get("last_activity_at")) or _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or _now()
        return (la, s.get("id") or "")
    out.sort(key=_key, reverse=True)

    # Apply cursor: return items strictly "after" cursor in this sort order
    if cursor:
        c_la = _parse_dt(cursor.get("last_activity_at"))
        c_id = cursor.get("id")
        if c_la is None or not isinstance(c_id, str):
            return _err("VALIDATION_ERROR", "Invalid page_token.")
        filtered = []
        for s in out:
            la = _parse_dt(s.get("last_activity_at")) or _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or _now()
            sid = s.get("id") or ""
            if (la, sid) < (c_la, c_id):
                filtered.append(s)
        out = filtered

    total = len(out)
    page = out[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        la = _parse_dt(last.get("last_activity_at")) or _parse_dt(last.get("updated_at")) or _parse_dt(last.get("created_at")) or _now()
        token_obj = {"last_activity_at": _iso(la), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(token_obj, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    # Observable dynamics: record a tool invocation in an actual session context if possible (pick a visible session)
    if sessions:
        _start_invocation(session_id=sessions[0].get("id"), input_payload={
            "client_key": client_key, "status": status, "browser_engine": browser_engine,
            "created_after": created_after, "created_before": created_before,
            "limit": limit, "page_token": page_token, "include_closed": include_closed
        }, tab_id=None)

    return {
        "data": {
            "sessions": page,
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_page_token": next_cursor,
        }
    }

def automation_session_get(id, client_key=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _today_key(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _log_invocation(invocations, session_id, status, inp, result=None, error_message=None):
        created = _iso(now)
        inv_id = _new_id("pws_call")
        inv_row = {
            "id": inv_id,
            "session_id": session_id,
            "tab_id": None,
            "tool_name": "automation_session_get",
            "input": inp,
            "status": status,
            "started_at": created,
            "ended_at": created,
            "duration_ms": int(max(0, (time.time() - t0) * 1000)),
            "error_message": error_message,
            "result": result,
            "created_at": created,
            "updated_at": created,
        }
        invocations.append(inv_row)
        return inv_row

    # Validate
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    if client_key is not None and (not isinstance(client_key, str) or not client_key.strip()):
        return _err("VALIDATION_ERROR", "client_key must be a non-empty string when provided.")

    sessions = _load("automation_sessions.json")
    invocations = _load("tool_invocations.json")
    keys = _load("client_keys.json")

    uses_keys = bool(keys) or any(isinstance(s, dict) and s.get("client_key_id") for s in sessions)

    key_row = None
    if uses_keys and client_key is not None:
        ck = client_key.strip()
        # Authenticate by id OR by client-visible value; store only has id and hash, so accept id only.
        key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == ck), None)
        if not key_row:
            inv = _log_invocation(invocations, "", "failed", {"id": id, "client_key": client_key}, result=None, error_message="invalid client key")
            _save("tool_invocations.json", invocations)
            return _err("UNAUTHORIZED", "Invalid client key.")
        if key_row.get("status") != "active":
            inv = _log_invocation(invocations, "", "failed", {"id": id, "client_key": client_key}, result=None, error_message="client key disabled/revoked")
            _save("tool_invocations.json", invocations)
            return _err("UNAUTHORIZED", "Client key is disabled or revoked.")
        key_row["last_used_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("client_keys.json", keys)

        # Enforce daily invocation limit (reads included)
        limit = key_row.get("daily_invocation_limit")
        if isinstance(limit, int):
            day = _today_key(now)
            used = 0
            for r in invocations:
                if not isinstance(r, dict):
                    continue
                ca = _parse_dt(r.get("created_at"))
                if ca and _today_key(ca) == day:
                    # if invocation row doesn't carry client_key_id, count all reads for this key by key last_used window is impossible;
                    # pragmatic: count only those with session_id belonging to key OR where input.client_key matches
                    inp = r.get("input") if isinstance(r.get("input"), dict) else {}
                    if inp.get("client_key") == ck:
                        used += 1
            if used >= limit:
                inv = _log_invocation(invocations, "", "failed", {"id": id, "client_key": client_key}, result=None, error_message="quota exceeded: daily invocation limit")
                _save("tool_invocations.json", invocations)
                return _err("QUOTA_EXCEEDED", "Daily invocation limit exceeded.", limit=limit)

    # Fetch session by id; do not conflate keys with session id
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == id.strip()), None)
    if not sess:
        inv = _log_invocation(invocations, "", "failed", {"id": id, "client_key": client_key}, result=None, error_message="session not found")
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Session not found.")

    # Visibility: if keys enabled, session must match caller key if provided
    if uses_keys and client_key is not None:
        if sess.get("client_key_id") and sess.get("client_key_id") != key_row.get("id"):
            inv = _log_invocation(invocations, sess.get("id"), "failed", {"id": id, "client_key": client_key}, result=None, error_message="session not visible to client key")
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "Session not found.")

    inv = _log_invocation(invocations, sess.get("id"), "succeeded", {"id": id, "client_key": client_key}, result={"session": sess}, error_message=None)
    _save("tool_invocations.json", invocations)

    # Update last_activity_at on reads as specified (each tool call)
    sess["last_activity_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    _save("automation_sessions.json", sessions)

    return {"session": sess, "invocation": inv}

def automation_session_create(client_key=None, browser_engine=None, headless=None, viewport_width=None, viewport_height=None, open_initial_tab=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}"

    def _log_invocation(session_id, input_payload, status="succeeded", result=None, error_message=None):
        invs = _load("tool_invocations.json")
        now = _now()
        inv = {
            "id": _gen_id("inv"),
            "session_id": session_id,
            "tab_id": None,
            "tool_name": "browser_install",  # use an allowed enum tool_name to ensure schema compatibility; represents session bootstrap
            "input": input_payload,
            "status": status,
            "started_at": _iso(now),
            "ended_at": _iso(now),
            "duration_ms": 0,
            "error_message": error_message,
            "result": result,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        invs.append(inv)
        _save("tool_invocations.json", invs)
        return inv

    # Defaults / validation
    if browser_engine is None:
        browser_engine = "chromium"
    if browser_engine not in ("chromium", "firefox", "webkit"):
        return _err("VALIDATION_ERROR", "browser_engine must be one of chromium, firefox, webkit.")
    if headless is None:
        headless = True
    if not isinstance(headless, bool):
        return _err("VALIDATION_ERROR", "headless must be a boolean.")
    if viewport_width is not None:
        if not isinstance(viewport_width, int) or isinstance(viewport_width, bool) or viewport_width < 100 or viewport_width > 10000:
            return _err("VALIDATION_ERROR", "viewport_width must be an integer between 100 and 10000.")
    if viewport_height is not None:
        if not isinstance(viewport_height, int) or isinstance(viewport_height, bool) or viewport_height < 100 or viewport_height > 10000:
            return _err("VALIDATION_ERROR", "viewport_height must be an integer between 100 and 10000.")
    if open_initial_tab is None:
        open_initial_tab = True
    if not isinstance(open_initial_tab, bool):
        return _err("VALIDATION_ERROR", "open_initial_tab must be a boolean.")

    keys = _load("client_keys.json")
    key_row = None
    if keys:
        if client_key is None or not isinstance(client_key, str) or not client_key.strip():
            return _err("UNAUTHORIZED", "client_key is required.")
        key_row = next((k for k in keys if k.get("id") == client_key.strip()), None)
        if not key_row:
            return _err("UNAUTHORIZED", "Invalid client_key.")
        if key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "Client key is disabled or revoked.")

        # Enforce daily session quota
        limit = key_row.get("daily_session_limit")
        if isinstance(limit, int):
            now = _now()
            start = datetime.datetime(now.year, now.month, now.day, tzinfo=now.tzinfo)
            sessions = _load("automation_sessions.json")
            used = 0
            for s in sessions:
                if s.get("client_key_id") != key_row.get("id"):
                    continue
                ca = _parse_dt(s.get("created_at"))
                if ca and ca >= start and ca <= now:
                    used += 1
            if used >= limit:
                return _err("RATE_LIMIT", "Daily session limit exceeded.", used_today=used, limit=limit)

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")

    now = _now()
    sid = _gen_id("sess")
    sess = {
        "id": sid,
        "client_key_id": key_row.get("id") if key_row else None,
        "browser_engine": browser_engine,
        "headless": headless,
        "viewport_width": viewport_width,
        "viewport_height": viewport_height,
        "current_tab_id": None,
        "status": "active",
        "last_error": None,
        "last_activity_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # Persist session
    sessions.append(sess)
    _save("automation_sessions.json", sessions)

    # Optionally open initial tab (policy)
    if open_initial_tab:
        # next tab_index
        existing = [t for t in tabs if t.get("session_id") == sid]
        next_index = (max([t.get("tab_index", -1) for t in existing]) + 1) if existing else 0
        tab_id = _gen_id("tab")
        tab = {
            "id": tab_id,
            "session_id": sid,
            "tab_index": int(next_index),
            "title": None,
            "current_url": None,
            "can_go_back": False,
            "can_go_forward": False,
            "status": "open",
            "opened_at": _iso(now),
            "closed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tabs.append(tab)
        _save("browser_tabs.json", tabs)

        # auto_select_new_tab true for initial tab
        sessions = _load("automation_sessions.json")
        for s in sessions:
            if s.get("id") == sid:
                s["current_tab_id"] = tab_id
                s["last_activity_at"] = _iso(now)
                s["updated_at"] = _iso(now)
                sess = s
                break
        _save("automation_sessions.json", sessions)

    # Log creation in event log via a tool invocation (schema requires tool_invocations)
    _log_invocation(sid, {
        "client_key": client_key,
        "browser_engine": browser_engine,
        "headless": headless,
        "viewport_width": viewport_width,
        "viewport_height": viewport_height,
        "open_initial_tab": open_initial_tab
    }, status="succeeded", result={"created": True}, error_message=None)

    # Update key last_used_at
    if key_row:
        keys = _load("client_keys.json")
        for k in keys:
            if k.get("id") == key_row.get("id"):
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("client_keys.json", keys)

    return {"data": sess}

def automation_session_update(id, client_key=None, status=None, viewport_width=None, viewport_height=None, current_tab_id=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _today_key(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _log_invocation(invocations, session_id, status_str, inp, result=None, error_message=None):
        created = _iso(now)
        inv_id = _new_id("pws_call")
        inv_row = {
            "id": inv_id,
            "session_id": session_id,
            "tab_id": None,
            "tool_name": "automation_session_update",
            "input": inp,
            "status": status_str,
            "started_at": created,
            "ended_at": created,
            "duration_ms": int(max(0, (time.time() - t0) * 1000)),
            "error_message": error_message,
            "result": result,
            "created_at": created,
            "updated_at": created,
        }
        invocations.append(inv_row)
        return inv_row

    # Validate id
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    if client_key is not None and (not isinstance(client_key, str) or not client_key.strip()):
        return _err("VALIDATION_ERROR", "client_key must be a non-empty string when provided.")

    allowed_status = ("active", "closing", "closed", "errored")
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "status must be one of: active, closing, closed, errored.")

    # Constraints: viewport_width/height null OR between 100 and 10000 (despite schema min=1)
    if viewport_width is not None:
        if not isinstance(viewport_width, int):
            return _err("VALIDATION_ERROR", "viewport_width must be an integer.")
        if not (100 <= viewport_width <= 10000):
            return _err("VALIDATION_ERROR", "viewport_width must be between 100 and 10000.")
    if viewport_height is not None:
        if not isinstance(viewport_height, int):
            return _err("VALIDATION_ERROR", "viewport_height must be an integer.")
        if not (100 <= viewport_height <= 10000):
            return _err("VALIDATION_ERROR", "viewport_height must be between 100 and 10000.")
    if current_tab_id is not None and not (isinstance(current_tab_id, str) or current_tab_id is None):
        return _err("VALIDATION_ERROR", "current_tab_id must be a string or null.")

    sessions = _load("automation_sessions.json")
    tabs = _load("browser_tabs.json")
    invocations = _load("tool_invocations.json")
    keys = _load("client_keys.json")

    uses_keys = bool(keys) or any(isinstance(s, dict) and s.get("client_key_id") for s in sessions)

    key_row = None
    if uses_keys and client_key is not None:
        ck = client_key.strip()
        key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == ck), None)
        if not key_row:
            inv = _log_invocation(invocations, "", "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="invalid client key")
            _save("tool_invocations.json", invocations)
            return _err("UNAUTHORIZED", "Invalid client key.")
        if key_row.get("status") != "active":
            inv = _log_invocation(invocations, "", "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="client key disabled/revoked")
            _save("tool_invocations.json", invocations)
            return _err("UNAUTHORIZED", "Client key is disabled or revoked.")

        # Enforce daily invocation limit (mutations included)
        limit = key_row.get("daily_invocation_limit")
        if isinstance(limit, int):
            day = _today_key(now)
            used = 0
            for r in invocations:
                if not isinstance(r, dict):
                    continue
                ca = _parse_dt(r.get("created_at"))
                if ca and _today_key(ca) == day:
                    inp = r.get("input") if isinstance(r.get("input"), dict) else {}
                    if inp.get("client_key") == ck:
                        used += 1
            if used >= limit:
                inv = _log_invocation(invocations, "", "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="quota exceeded: daily invocation limit")
                _save("tool_invocations.json", invocations)
                return _err("QUOTA_EXCEEDED", "Daily invocation limit exceeded.", limit=limit)

        key_row["last_used_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("client_keys.json", keys)

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == id.strip()), None)
    if not sess:
        inv = _log_invocation(invocations, "", "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="session not found")
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Session not found.")

    if uses_keys and client_key is not None:
        if sess.get("client_key_id") and sess.get("client_key_id") != key_row.get("id"):
            inv = _log_invocation(invocations, sess.get("id"), "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="session not visible to client key")
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "Session not found.")

    # Validate current_tab_id belongs to session and is open (or allow null to detach)
    if current_tab_id is not None:
        if current_tab_id is None:
            pass
        else:
            t = next((x for x in tabs if isinstance(x, dict) and x.get("id") == current_tab_id and x.get("session_id") == sess.get("id")), None)
            if not t:
                inv = _log_invocation(invocations, sess.get("id"), "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="current_tab_id not found for session")
                _save("tool_invocations.json", invocations)
                return _err("NOT_FOUND", "current_tab_id does not exist in this session.", reason="tab_not_found")
            if t.get("status") != "open":
                inv = _log_invocation(invocations, sess.get("id"), "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="current_tab_id must be open")
                _save("tool_invocations.json", invocations)
                return _err("CONFLICT", "current_tab_id must reference an open tab.", reason="tab_not_open")

    # Lifecycle transition enforcement
    transitions = {
        "active": set(["closing", "errored"]),
        "closing": set(["closed", "errored"]),
        "closed": set([]),
        "errored": set(["closing", "closed"]),
    }
    if status is not None:
        cur = sess.get("status")
        if cur not in transitions:
            inv = _log_invocation(invocations, sess.get("id"), "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="unknown current status")
            _save("tool_invocations.json", invocations)
            return _err("CONFLICT", "Unknown current session lifecycle status.", current_status=cur)
        if status != cur and status not in transitions.get(cur, set()):
            inv = _log_invocation(invocations, sess.get("id"), "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="invalid lifecycle transition")
            _save("tool_invocations.json", invocations)
            return _err("INVALID_TRANSITION", f"Invalid session status transition: {cur} → {status}.", from_status=cur, to_status=status)

    # Apply updates (no success without effect)
    changed = False
    if status is not None and status != sess.get("status"):
        sess["status"] = status
        if status != "errored":
            sess["last_error"] = None
        changed = True
    if viewport_width is not None and viewport_width != sess.get("viewport_width"):
        sess["viewport_width"] = viewport_width
        changed = True
    if viewport_height is not None and viewport_height != sess.get("viewport_height"):
        sess["viewport_height"] = viewport_height
        changed = True
    if current_tab_id is not None and current_tab_id != sess.get("current_tab_id"):
        sess["current_tab_id"] = current_tab_id
        changed = True

    if not changed:
        inv = _log_invocation(invocations, sess.get("id"), "failed", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result=None, error_message="no changes applied")
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "No changes to apply.", reason="no_effect", invocation_id=inv["id"])

    sess["last_activity_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    _save("automation_sessions.json", sessions)

    inv = _log_invocation(invocations, sess.get("id"), "succeeded", {"id": id, "client_key": client_key, "status": status, "viewport_width": viewport_width, "viewport_height": viewport_height, "current_tab_id": current_tab_id}, result={"session": sess}, error_message=None)
    _save("tool_invocations.json", invocations)

    return {"session": sess, "invocation": inv}

def tool_invocation_list(session_id, client_key=None, tab_id=None, tool_name=None, status=None, created_after=None, created_before=None, limit=None, page_token=None, **_extra):
    import json, os, datetime, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _iso(now)

    def _parse_dt(s):
        if s is None: return None
        if isinstance(s, datetime.datetime): return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str): return None
        try:
            x = s
            if x.endswith("Z"): x = x[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _tok_enc(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _tok_dec(tok):
        if not isinstance(tok, str) or not tok: return None
        pad = "=" * (-len(tok) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Validate base params
    if not isinstance(session_id, str) or not session_id.strip():
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string.")
    if client_key is not None and (not isinstance(client_key, str) or not client_key.strip()):
        return _err("VALIDATION_ERROR", "client_key must be a non-empty string when provided.")
    if tab_id is not None and (not isinstance(tab_id, str) or not tab_id.strip()):
        return _err("VALIDATION_ERROR", "tab_id must be a non-empty string when provided.")
    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string when provided.")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or not (1 <= limit <= 500):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")

    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 datetime string.")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 datetime string.")

    sessions = _load("automation_sessions.json")
    invocations = _load("tool_invocations.json")
    keys = _load("client_keys.json")

    created = _iso(now)

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        # log failed list call (against empty session_id)
        inv_row = {
            "id": _new_id("pws_call"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "tool_invocation_list",
            "input": {"session_id": session_id, **({} if client_key is None else {"client_key": client_key}),
                      **({} if tab_id is None else {"tab_id": tab_id}),
                      **({} if tool_name is None else {"tool_name": tool_name}),
                      **({} if status is None else {"status": status}),
                      **({} if created_after is None else {"created_after": created_after}),
                      **({} if created_before is None else {"created_before": created_before}),
                      "limit": limit, **({} if page_token is None else {"page_token": page_token})},
            "status": "failed",
            "started_at": created,
            "ended_at": created,
            "duration_ms": int(max(0, (time.time() - t0) * 1000)),
            "error_message": "session not found",
            "result": None,
            "created_at": created,
            "updated_at": created,
        }
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Session not found.")

    # Authenticate if client_key provided; do NOT compare to hashes.
    uses_keys = bool(keys) or any(isinstance(s, dict) and s.get("client_key_id") for s in sessions)
    key_row = None
    if uses_keys and client_key is not None:
        key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == client_key.strip()), None)
        if not key_row:
            return _err("UNAUTHORIZED", "Invalid client key.")
        if key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "Client key is not active.", key_status=key_row.get("status"))
        if sess.get("client_key_id") and sess.get("client_key_id") != key_row.get("id"):
            return _err("UNAUTHORIZED", "session not accessible for this client_key")

    # Apply page_token cursor as created_at lower bound (opaque)
    cursor_dt = None
    if page_token is not None:
        tok = _tok_dec(page_token)
        if not isinstance(tok, dict) or tok.get("session_id") != session_id:
            return _err("VALIDATION_ERROR", "Invalid page_token.")
        cursor_dt = _parse_dt(tok.get("after"))
        if cursor_dt is None:
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    # Filter
    rows = [r for r in invocations if isinstance(r, dict) and r.get("session_id") == session_id]
    if tab_id is not None:
        rows = [r for r in rows if r.get("tab_id") == tab_id]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if ca is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= ca]
    if cb is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) < cb]
    if cursor_dt is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) > cursor_dt]

    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""))

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        next_cursor = _tok_enc({"session_id": session_id, "after": page[-1].get("created_at")})

    # Log this read call as an invocation too (append-only)
    inv_row = {
        "id": _new_id("pws_call"),
        "session_id": session_id,
        "tab_id": tab_id,
        "tool_name": "tool_invocation_list",
        "input": {"session_id": session_id, **({} if client_key is None else {"client_key": client_key}),
                  **({} if tab_id is None else {"tab_id": tab_id}),
                  **({} if tool_name is None else {"tool_name": tool_name}),
                  **({} if status is None else {"status": status}),
                  **({} if created_after is None else {"created_after": created_after}),
                  **({} if created_before is None else {"created_before": created_before}),
                  "limit": limit, **({} if page_token is None else {"page_token": page_token})},
        "status": "succeeded",
        "started_at": created,
        "ended_at": created,
        "duration_ms": int(max(0, (time.time() - t0) * 1000)),
        "error_message": None,
        "result": {"returned": len(page), "total_matched": total, "has_more": has_more},
        "created_at": created,
        "updated_at": created,
    }
    invocations.append(inv_row)

    # Update session activity and key usage (if resolvable)
    sess["last_activity_at"] = created
    sess["updated_at"] = created
    if key_row is None and uses_keys and sess.get("client_key_id"):
        kr = next((k for k in keys if isinstance(k, dict) and k.get("id") == sess.get("client_key_id")), None)
        if kr and kr.get("status") == "active":
            key_row = kr
    if key_row is not None:
        key_row["last_used_at"] = created
        key_row["updated_at"] = created

    _save("automation_sessions.json", sessions)
    _save("client_keys.json", keys)
    _save("tool_invocations.json", invocations)

    return {
        "data": page,
        "meta": {"total_matched": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
        "invocation": inv_row
    }

def client_key_whoami(client_key, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0112000" if __import__("os").path.isdir("./environment_mix/0112000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _today_bounds_local():
        local_now = datetime.datetime.now()
        start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + datetime.timedelta(days=1)
        return start, end

    def _dt_to_local_naive(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            dt = _parse_dt(dt)
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            return dt
        return dt.astimezone().replace(tzinfo=None)

    # ---- Validate ----
    if not isinstance(client_key, str) or not client_key.strip():
        return _err("UNAUTHORIZED", "client_key is required")

    keys = _load("client_keys.json")
    if len(keys) == 0:
        return _err("UNAUTHORIZED", "client keys are not enabled on this server")

    ck = client_key.strip()
    ck_hash = hashlib.sha256(ck.encode("utf-8")).hexdigest()
    row = next((k for k in keys if k.get("id") == ck or k.get("key_hash") == ck or k.get("key_hash") == ck_hash), None)
    if not row:
        return _err("UNAUTHORIZED", "invalid client_key")

    if row.get("status") in ("disabled", "revoked"):
        return _err("UNAUTHORIZED", "client_key is disabled or revoked", status=row.get("status"))

    # ---- Usage for today (server timezone / local) ----
    sessions = _load("automation_sessions.json")
    invocations = _load("tool_invocations.json")
    artifacts = _load("artifacts.json")

    start, end = _today_bounds_local()

    sess_today = 0
    for s in sessions:
        if s.get("client_key_id") != row.get("id"):
            continue
        created = _dt_to_local_naive(s.get("created_at"))
        if created is None:
            continue
        if start <= created < end:
            sess_today += 1

    inv_today = 0
    for r in invocations:
        sid = r.get("session_id")
        srow = next((s for s in sessions if s.get("id") == sid), None)
        if not srow or srow.get("client_key_id") != row.get("id"):
            continue
        created = _dt_to_local_naive(r.get("created_at"))
        if created is None:
            continue
        if start <= created < end:
            inv_today += 1

    art_bytes_today = 0
    art_count_today = 0
    for a in artifacts:
        sid = a.get("session_id")
        srow = next((s for s in sessions if s.get("id") == sid), None)
        if not srow or srow.get("client_key_id") != row.get("id"):
            continue
        created = _dt_to_local_naive(a.get("created_at"))
        if created is None:
            continue
        if start <= created < end:
            art_count_today += 1
            bs = a.get("byte_size")
            if isinstance(bs, int) and bs >= 0:
                art_bytes_today += bs

    # ---- Persist last_used_at ----
    row["last_used_at"] = _iso(now)
    row["updated_at"] = _iso(now)
    _save("client_keys.json", keys)

    entitlements = {
        "daily_session_limit": row.get("daily_session_limit"),
        "daily_invocation_limit": row.get("daily_invocation_limit"),
        "daily_artifact_bytes_limit": row.get("daily_artifact_bytes_limit"),
    }
    usage = {
        "today": {
            "sessions_created": sess_today,
            "invocations": inv_today,
            "artifact_bytes": art_bytes_today,
            "artifacts_created": art_count_today,
            "window_start_local": start.isoformat(),
            "window_end_local": end.isoformat(),
        }
    }
    effective = {
        "sessions_remaining": None if entitlements["daily_session_limit"] is None else max(entitlements["daily_session_limit"] - sess_today, 0),
        "invocations_remaining": None if entitlements["daily_invocation_limit"] is None else max(entitlements["daily_invocation_limit"] - inv_today, 0),
        "artifact_bytes_remaining": None if entitlements["daily_artifact_bytes_limit"] is None else max(entitlements["daily_artifact_bytes_limit"] - art_bytes_today, 0),
    }

    # Note: whoami itself should be observable; record in tool_invocations with no session context if possible.
    # Schema requires session_id for tool_invocations; so we cannot log here without a session. Return without logging.

    return {
        "client_key": {
            "id": row.get("id"),
            "label": row.get("label"),
            "status": row.get("status"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
            "last_used_at": row.get("last_used_at"),
        },
        "entitlements": entitlements,
        "usage": usage,
        "effective": effective,
        "server_time_utc": _iso(now),
        "latency_ms": int((time.time() - t0) * 1000),
    }
